class ArmyGroup:
    def __init__(self, army_id, name, general=None, color_id=3):
        self.id = army_id
        self.name = name
        self.general = general
        self.color_id = color_id
        self.division_ids = []
        self.order_type = None  # None, "FRONTLINE", "OFFENSIVE", "SPEARHEAD", "GARRISON", "FALLBACK"
        self.order_active = False
        self.planning_bonus = 0.0  # 0 to 25.0%
        self.target_nation_id = None
        self.frontline_tiles = []
        self.offensive_line = []
        self.spearhead_path = []
        self.fallback_tiles = []
        self.garrison_tiles = []

    def get_overcap_debuff(self):
        count = len(self.division_ids)
        if count <= ARMY_CAP:
            return 0.0
        excess = count - ARMY_CAP
        return min(0.75, excess * 0.05)  # -5% per division over HOI4's 24, max -75%

def init_player_armies(nation_name, initial_player_units):
    global PLAYER_ARMIES
    PLAYER_ARMIES.clear()
    country_clean = nation_name.replace(" (YOU)", "").strip()
    generals = GENERALS_POOL.get(country_clean, GENERALS_POOL["Generic"])

    mobile = [u for u in initial_player_units if u.kind in ("arm", "mot")]
    foot = sorted((u for u in initial_player_units if u not in mobile), key=lambda u: (u.x, u.y))
    k = max(1, -(-len(foot) // ARMY_CAP))
    groups = [foot[i * len(foot) // k:(i + 1) * len(foot) // k] for i in range(k)]
    names = [f"{ordinal(i + 1)} Army" for i in range(len(groups))]
    if mobile:
        groups.append(mobile)
        names.append("Panzer Corps" if country_clean == "German Reich" else "Mobile Corps")
    colors = (3, 2, 6, 5, 4, 7, 1)
    for i, (grp, name) in enumerate(zip(groups, names)):
        a = ArmyGroup(i + 1, name, general=generals[i] if i < len(generals) else None, color_id=colors[i % len(colors)])
        PLAYER_ARMIES.append(a)
        for u in grp:
            a.division_ids.append(u.id)
            u.army_id = a.id
    if len(PLAYER_ARMIES) < 9:
        PLAYER_ARMIES.append(ArmyGroup(len(PLAYER_ARMIES) + 1, "Home Garrison",
                                       general=generals[len(PLAYER_ARMIES)] if len(generals) > len(PLAYER_ARMIES) else None, color_id=5))


class Division:
    def __init__(self, d_id, nation_id, x, y, template, name=None):
        self.id, self.nation_id = d_id, nation_id
        self.key = template.get("key", "inf")
        self.type = template['name']
        if name is None:
            name = name_division(NATIONS[nation_id], self.key) if nation_id < len(NATIONS) else f"{template['name']} {d_id}"
        self.name = name
        self.x, self.y = x, y
        self.target_x, self.target_y = None, None
        self.path = []
        self.move_cooldown = 0
        self.hp = self.max_hp = template['hp']
        self.org = self.max_org = template.get('org', 60)
        self.apply_template(template)
        self.attacking = None    # the neighbouring tile we are attacking (HOI4: attackers stay where they are)
        self.safe_path = False   # route only through our and our allies' land (AI repositioning)
        self.xp = 10.0           # 'Trained'
        self.entrench = 0.0      # days dug in (max 5, +4% defence each)
        self.in_battle = 0
        self.moved = False
        self.retreat_hours = 0   # just fell back: won't attack again for a day
        self.landing = 0         # hours of amphibious-assault penalty left
        self.sea = None          # dict while carried by convoy (naval transfer or invasion)
        self.transfer = None     # dict while marching to the port to embark
        self.is_guarding = False
        self.order = None
        self.army_id = None

    def apply_template(self, t):
        """Take a template's stats (also when the template is changed in the designer): strength and
        organisation keep their share."""
        hpf = max(0.0, self.hp) / self.max_hp if self.max_hp else 1.0
        orgf = self.org / self.max_org if self.max_org else 1.0
        self.key, self.type, self.symbol = t["key"], t["name"], t["symbol"]
        self.speed = t.get("speed", 1)
        self.max_hp, self.max_org = t["hp"], max(1.0, t.get("org", 60))
        self.hp, self.org = self.max_hp * hpf, self.max_org * orgf
        self.soft, self.hard = t.get('soft', 15), t.get('hard', 1)
        self.base_def, self.brk = t.get('def', 10), t.get('brk', 10)
        self.armor, self.pierce, self.hardness = t.get('armor', 0), t.get('pierce', 4), t.get('hardness', 0.0)
        self.aa = t.get('aa', 0.0)

    @property
    def kind(self):
        return TEMPLATE_BY_KEY[self.key]["kind"] if self.key in TEMPLATE_BY_KEY else "inf"

    @property
    def attack(self):
        """Soft attack it brings right now (strength, plans, generals, experience and tech included)."""
        a, _ = division_bonus(self)
        return int(round(self.soft * a * (0.25 + 0.75 * max(0, self.hp) / self.max_hp)))

    @property
    def defense(self):
        _, d = division_bonus(self)
        return int(round(self.base_def * d * (1 + 0.04 * self.entrench)))

    def route(self, tx, ty, world_map, political_map):
        nat = NATIONS[self.nation_id]
        if self.safe_path:  # behind our own lines: enemy land is closed except the last step
            return astar_path(world_map, political_map, (self.x, self.y), (tx, ty), self.nation_id, set(),
                              set(nat["has_access_to"]) | friends_of(nat))
        return astar_path(world_map, political_map, (self.x, self.y), (tx, ty),
                          self.nation_id, nat["at_war_with"], nat["has_access_to"])

    def set_target(self, tx, ty, world_map, political_map, safe=False):
        if self.sea is not None:
            return
        self.target_x, self.target_y = tx, ty
        self.safe_path = safe
        self.path = self.route(tx, ty, world_map, political_map)
        if not self.path and (self.x, self.y) != (tx, ty):
            self.target_x, self.target_y = None, None

    def update_movement(self, world_map, political_map):
        if self.sea is not None:
            return False
        if not self.path and (self.target_x is not None and self.target_y is not None):
            if (self.x, self.y) != (self.target_x, self.target_y):
                self.path = self.route(self.target_x, self.target_y, world_map, political_map)
            if not self.path:
                self.target_x, self.target_y = None, None
                return False

        if not self.path:
            self.attacking = None
            return False

        nx, ny = self.path[0]

        # Safety: never step into ocean
        if world_map[ny][nx] == 0:
            self.path = []
            self.target_x, self.target_y = None, None
            return False

        owner = political_map[ny][nx]
        nat = NATIONS[self.nation_id]
        if owner != -1 and owner != self.nation_id and owner not in nat["at_war_with"] and owner not in nat["has_access_to"] \
                and owner not in friends_of(nat):
            self.path = []
            self.target_x, self.target_y = None, None
            return False

        # Enemy troops hold the next tile: attack it from here (HOI4) - the tile is ours to enter once they
        # are gone. A broken or freshly beaten division waits to recover instead.
        if any(e.nation_id in nat["at_war_with"] and e.sea is None for e in TILE_UNITS.get((nx, ny), ())):
            self.attacking = None if (self.org < 0.3 * self.max_org or self.retreat_hours) else (nx, ny)
            if self.move_cooldown > 0:
                self.move_cooldown -= 1
            return False
        self.attacking = None
        if owner in nat["at_war_with"] and (self.org < 0.3 * self.max_org or self.retreat_hours):
            return False  # too battered to advance: wait and recover

        if self.move_cooldown > 0:
            self.move_cooldown -= 1
            return False

        self.path.pop(0)
        self.x, self.y = nx, ny
        self.moved = True

        # Movement cooldown based on speed:
        # Player units (nation_id == 0) are significantly faster for snappy and responsive field operations:
        # Player: Motorized=1 (very fast), Armor/Cavalry=2 (swift), Infantry=3 (double speed)
        # AI: Motorized=2, Armor/Cavalry=4, Infantry=6
        if self.nation_id == 0:
            base_cd = 3 if self.speed == 1 else (2 if self.speed == 2 else 1)
        else:
            base_cd = 6 if self.speed == 1 else (4 if self.speed == 2 else 2)

        if self.nation_id == 0 and getattr(self, 'army_id', None) is not None:
            army = next((a for a in PLAYER_ARMIES if a.id == self.army_id), None)
            if army and army.get_overcap_debuff() > 0:
                base_cd += 2  # Supply & command penalty for overcapacity

        terrain = world_map[ny][nx]
        ter = TERRAIN_GRID[ny][nx] if TERRAIN_GRID else "p"
        if self.nation_id == 0:
            if terrain >= 3 and not (self.kind == "mtn"):
                base_cd += 1  # Reduced mountain penalty for player
        else:
            if terrain >= 3:
                base_cd += 1 if self.kind == "mtn" else 3  # Mountain penalty (mountaineers barely notice)
            elif terrain == 1:
                base_cd += 1  # Coastal/hills penalty
        if self.kind in ("mot", "arm") and ter in ("f", "s"):
            base_cd += 1  # vehicles bog down in forests and marshes
        if AIR["spd"]:  # enemy air superiority: up to -30% speed (HOI4)
            p = AIR["spd"].get(AIR_ZONE_GRID[ny][nx])
            if p and p.get(self.nation_id):
                base_cd += int(base_cd * 0.43 * p[self.nation_id] + 0.5)
        self.move_cooldown = base_cd

        if not self.path or (self.x == self.target_x and self.y == self.target_y):
            self.target_x, self.target_y = None, None

        return True

    def move_towards_target(self, political_map, world_map=None):
        if world_map is None:
            # Fallback direct step
            if self.target_x is not None and self.target_y is not None:
                nx, ny = self.x, self.y
                if self.x < self.target_x: nx += 1
                elif self.x > self.target_x: nx -= 1
                if self.y < self.target_y: ny += 1
                elif self.y > self.target_y: ny -= 1
                self.x, self.y = nx, ny
                if self.x == self.target_x and self.y == self.target_y:
                    self.target_x, self.target_y = None, None
                return True
            return False
        return self.update_movement(world_map, political_map)


class GradientNoise:
    """Stands in for the perlin-noise package when it isn't installed: classic 2-D gradient (Perlin) noise, used the
    same way - GradientNoise(octaves, seed)([x, y]) - where octaves is the number of grid cells per unit."""

    def __init__(self, octaves=1, seed=1):
        self.octaves, self.seed, self.grads = octaves, seed, {}

    def grad(self, ix, iy):
        g = self.grads.get((ix, iy))
        if g is None:   # a random direction per grid corner, the same every time for this seed
            a = random.Random(ix * 73856093 ^ iy * 19349663 ^ self.seed * 83492791).random() * 2 * math.pi
            g = self.grads[(ix, iy)] = (math.cos(a), math.sin(a))
        return g

    def __call__(self, coords):
        x, y = coords[0] * self.octaves, coords[1] * self.octaves
        x0, y0 = math.floor(x), math.floor(y)

        def corner(ix, iy):
            gx, gy = self.grad(ix, iy)
            return gx * (x - ix) + gy * (y - iy)
        fx, fy = x - x0, y - y0
        u = fx * fx * fx * (fx * (fx * 6 - 15) + 10)   # smooth fade between the corners
        v = fy * fy * fy * (fy * (fy * 6 - 15) + 10)
        top = corner(x0, y0) + u * (corner(x0 + 1, y0) - corner(x0, y0))
        bottom = corner(x0, y0 + 1) + u * (corner(x0 + 1, y0 + 1) - corner(x0, y0 + 1))
        return top + v * (bottom - top)


def generate_world():
    seed = random.randint(1, 10000)
    Noise = PerlinNoise or GradientNoise
    noise1, noise2 = Noise(
        octaves=3, seed=seed), Noise(octaves=6, seed=seed)
    world = [[0 for _ in range(WORLD_WIDTH)] for _ in range(WORLD_HEIGHT)]
    for y in range(WORLD_HEIGHT):
        for x in range(WORLD_WIDTH):
            val = noise1([x/WORLD_WIDTH, y/WORLD_HEIGHT]) + \
                0.5 * noise2([x/WORLD_WIDTH, y/WORLD_HEIGHT])
            world[y][x] = 1 if val < 0.05 else 2
            if val < -0.15:
                world[y][x] = 0
    return world


