def parse_res(text):
    out = {}
    for part in (text or "").split():
        k, v = part.split(":")
        out[k] = out.get(k, 0) + int(v)
    return out


def state_slots(pop_millions, used):
    slots = 12
    for limit, k in SLOT_SIZES:
        if pop_millions < limit:
            slots = k
            break
    return max(slots, used + 1)


def build_states(world_map, political_map, historical):
    """Split every country into states: HOI4's 1936 states on the historical map (placed by their real
    position, each taking the land nearest it), a state around each city on random maps."""
    STATES.clear()
    STATE_GRID.clear()
    STATE_GRID.extend([[-1] * WORLD_WIDTH for _ in range(WORLD_HEIGHT)])
    by_key = {nation_key(n): n for n in NATIONS}
    seeds = []
    if historical:
        for owner, name, x, y, pop, civ, mil, dock, res, size in STATES_1936:
            n = by_key.get(owner)
            if owner and n is None:
                continue
            seeds.append({"name": name, "core": n["id"] if n else -1, "x": x, "y": y, "pop": pop, "civ": civ, "mil": mil,
                          "dock_w": dock, "res": parse_res(res), "size": size, "infra": STATE_INFRA.get(owner, 2)})
    else:
        for n in NATIONS:
            tiles = [(x, y) for y in range(WORLD_HEIGHT) for x in range(WORLD_WIDTH)
                     if world_map[y][x] and political_map[y][x] == n["id"]]
            if not tiles:
                continue
            data = next((d for d in ALL_NATIONS_DATA if d["name"] == nation_key(n)), {"ind": 3, "manpower": 300})
            k = max(1, min(10, len(tiles) // 40))
            spots = [c for c in n["cities"] if c in set(tiles)][:k]
            rest = [t for t in tiles if t not in spots]
            random.shuffle(rest)
            spots += rest[:k - len(spots)]
            civ, mil = data["ind"], max(1, data["ind"] // 2)
            for i, (x, y) in enumerate(spots):
                seeds.append({"name": CITY_NAMES.get((x, y)) or f"{SHORT_NAMES.get(nation_key(n), nation_key(n))} {i + 1}",
                              "core": n["id"], "x": x, "y": y, "pop": data["manpower"] * 0.02 / len(spots),
                              "civ": civ // len(spots) + (1 if i < civ % len(spots) else 0),
                              "mil": mil // len(spots) + (1 if i < mil % len(spots) else 0),
                              "dock_w": 1, "res": {"steel": 4} if i == 0 else {}, "size": 1.0, "infra": 2})
    # every tile belongs to the nearest state of its 1936 owner on the same piece of land
    by_owner = {}
    for i, s in enumerate(seeds):
        by_owner.setdefault(s["core"], []).append(i)
    pick = {}
    for y in range(WORLD_HEIGHT):
        for x in range(WORLD_WIDTH):
            if not world_map[y][x]:
                continue
            o = CORE_OWNER[y][x] if CORE_OWNER else political_map[y][x]
            cand = by_owner.get(o)
            if not cand:
                continue
            lm = LANDMASS[y][x] if LANDMASS else 0
            use = pick.get((o, lm))
            if use is None:
                use = pick[(o, lm)] = [i for i in cand if not LANDMASS or LANDMASS[seeds[i]["y"]][seeds[i]["x"]] == lm] or cand
            best, bd = -1, 1e18
            for i in use:
                s = seeds[i]
                d = ((x - s["x"]) ** 2 + ((y - s["y"]) * 2.3) ** 2) / (s["size"] * s["size"])
                if d < bd:
                    best, bd = i, d
            if o == -1 and bd > 81:
                continue  # only the unclaimed land right around the state (Albania)
            STATE_GRID[y][x] = best
    tiles_of = {}
    for y in range(WORLD_HEIGHT):
        for x in range(WORLD_WIDTH):
            if STATE_GRID[y][x] >= 0:
                tiles_of.setdefault(STATE_GRID[y][x], []).append((x, y))
    remap = {}
    for i, s in enumerate(seeds):
        tiles = tiles_of.get(i)
        if not tiles:
            continue
        sid = len(STATES)
        remap[i] = sid
        vx, vy = (s["x"], s["y"]) if (s["x"], s["y"]) in set(tiles) else tiles[0]
        coastal = any(0 <= x + dx < WORLD_WIDTH and 0 <= y + dy < WORLD_HEIGHT and world_map[y + dy][x + dx] == 0
                      for x, y in tiles for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)))
        STATES.append({"id": sid, "name": s["name"], "core": s["core"], "x": vx, "y": vy, "tiles": tiles,
                       "pop": int(s["pop"] * 1_000_000), "civ": s["civ"], "mil": s["mil"], "dock": 0, "dock_w": s["dock_w"],
                       "refinery": 0, "infra": s["infra"], "fort": 0, "res": dict(s["res"]), "coastal": coastal,
                       "slots": 0, "controller": s["core"], "owner": s["core"],
                       "resist": 0.0, "comply": 0.0, "sabotage": 0, "occ_by": None, "vp": 0})
    for y in range(WORLD_HEIGHT):
        row = STATE_GRID[y]
        for x in range(WORLD_WIDTH):
            if row[x] >= 0:
                row[x] = remap.get(row[x], -1)
    # each country's dockyards (HOI4's numbers) go to its shipbuilding states
    for n in NATIONS:
        total = n.get("dockyards", 0)
        coast = [s for s in STATES if s["core"] == n["id"] and s["coastal"]]
        if not total or not coast:
            continue
        weights = [s["dock_w"] for s in coast]
        if not sum(weights):
            weights = [1] * len(coast)
        raw = [total * w / sum(weights) for w in weights]
        got = [int(r) for r in raw]
        for i in sorted(range(len(coast)), key=lambda i: raw[i] - got[i], reverse=True)[:total - sum(got)]:
            got[i] += 1
        for s, k in zip(coast, got):
            s["dock"] = k
    for s in STATES:
        s["slots"] = state_slots(s["pop"] / 1e6, s["civ"] + s["mil"] + s["dock"])
    # neighbours by land (the peace conference: who borders whom) and each state's cities (its victory points)
    STATE_ADJ.clear()
    STATE_ADJ.extend(set() for _ in STATES)
    for y in range(WORLD_HEIGHT):
        row = STATE_GRID[y]
        for x in range(WORLD_WIDTH):
            a = row[x]
            if a < 0:
                continue
            for nx, ny in ((x + 1, y), (x, y + 1)):
                if nx < WORLD_WIDTH and ny < WORLD_HEIGHT:
                    b = STATE_GRID[ny][nx]
                    if b >= 0 and b != a:
                        STATE_ADJ[a].add(b)
                        STATE_ADJ[b].add(a)
    for n in NATIONS:
        for i, c in enumerate(n["cities"]):
            s = state_at(*c)
            if s:
                s["vp"] += {"capital": 8, "medium": 3, "small": 1}[CITY_SIZES.get(c, "capital" if i == 0 else "medium")]


def industry_labels(cam_x, cam_y, vw, vh, capitals):
    """Labels for the state map: '4 3 1 8/12' = civilian / military / dockyards, then building slots
    used/cap, centred on each state's main town and shortened (or left out) where the state is too narrow."""
    labels = {}
    taken = set()
    hd = HD["on"]

    def attr(fg):
        if hd:
            pair = hd_exact_pair(fg, 235)
            if pair:
                return curses.color_pair(pair) | curses.A_BOLD
        return curses.color_pair({226: 3, 203: 1, 81: 6}.get(fg, 7)) | curses.A_BOLD

    for s in sorted(STATES, key=lambda s: -(s["civ"] + s["mil"] + s["dock"])):
        if not (cam_x <= s["x"] < cam_x + vw and cam_y <= s["y"] < cam_y + vh) or not (s["civ"] + s["mil"] + s["dock"]):
            continue
        used = used_slots(s)
        parts_full = [(str(s["civ"]), 226), (" ", 252), (str(s["mil"]), 203)] + \
                     ([(" ", 252), (str(s["dock"]), 81)] if s["dock"] else []) + [(f" {used}/{s['slots']}", 252)]
        options = [parts_full] + ([[(str(s["civ"]), 226), (" ", 252), (str(s["mil"]), 203)]] if s["civ"] + s["mil"] else []) + \
                  [[(f"{used}/{s['slots']}", 252)]]
        placed = False
        for dy in (0, -1, 1):
            y = s["y"] + dy
            if not (cam_y <= y < cam_y + vh):
                continue
            # the stretch of this state's land on that row around the main town
            xl = xr = s["x"]
            while xl - 1 >= 0 and STATE_GRID[y][xl - 1] == s["id"]:
                xl -= 1
            while xr + 1 < WORLD_WIDTH and STATE_GRID[y][xr + 1] == s["id"]:
                xr += 1
            if STATE_GRID[y][s["x"]] != s["id"]:
                continue
            for parts in options:
                text_len = sum(len(t) for t, _ in parts)
                if text_len > xr - xl + 2:
                    continue
                x0 = max(xl - 1, min(s["x"] - text_len // 2, xr + 1 - text_len + 1))
                cells = [(x0 + i, y) for i in range(text_len)]
                if any(c in taken or c in capitals for c in cells) or x0 < cam_x or x0 + text_len > cam_x + vw:
                    continue
                i = 0
                for t, fg in parts:
                    for ch in t:
                        labels[(x0 + i, y)] = (ch, attr(fg))
                        i += 1
                taken.update((x, y + d) for x in range(x0 - 1, x0 + text_len + 1) for d in (-1, 0, 1))
                placed = True
                break
            if placed:
                break
    return labels


def state_at(x, y):
    if STATE_GRID and 0 <= y < WORLD_HEIGHT and 0 <= x < WORLD_WIDTH:
        sid = STATE_GRID[y][x]
        return STATES[sid] if sid >= 0 else None
    return None


def used_slots(s):
    return s["civ"] + s["mil"] + s["dock"] + s["refinery"]


def manpower_rate(n):
    """Share of the population the conscription law lets us call up (HOI4: 1.5% - 20%)."""
    return CONSCRIPTION_LAWS[n["laws"]["conscription"]]["pct"] * ECONOMY_LAWS[n["laws"]["economy"]].get("manpower", 1.0)


def update_industry(political_map):
    """Who controls which state, and what every country gets from them: factories, dockyards, resources and
    recruits. Our own states give everything (those that aren't our core only a fifth of their recruits);
    occupied states give what their compliance allows (see state_shares). Puppets send their overlord half
    their resources."""
    for s in STATES:
        cnt = {}
        for x, y in s["tiles"]:
            o = political_map[y][x]
            cnt[o] = cnt.get(o, 0) + 1
        vp = political_map[s["y"]][s["x"]]
        s["controller"] = max(cnt, key=lambda o: (cnt[o], o == vp))
    sums = {n["id"]: {"civ": 0.0, "mil": 0.0, "dock": 0.0, "pop": 0.0, "res": {r: 0.0 for r in RESOURCES}} for n in NATIONS}
    for s in STATES:
        c = s["controller"]
        if c < 0 or c not in sums:
            continue
        if s["owner"] == -1:
            s["owner"] = c   # unclaimed land someone has taken (Albania) is theirs
        f, fp = state_shares(s, c)
        f *= 1 - s.get("bomb", 0.0)   # bombed factories are out until repaired
        t = sums[c]
        t["civ"] += s["civ"] * f
        t["mil"] += s["mil"] * f
        t["dock"] += s["dock"] * f
        t["pop"] += s["pop"] * fp
        for r, v in s["res"].items():
            t["res"][r] += v * f
        if s["refinery"]:
            t["res"]["oil"] += 4 * s["refinery"] * f
            t["res"]["rubber"] += 2 * s["refinery"] * f
    for n in NATIONS:
        t = sums[n["id"]]
        off = STATE_OFFMAP.get(nation_key(n)) if n["is_alive"] else None
        if off:
            t["civ"] += off["civ"]
            t["mil"] += off["mil"]
            t["pop"] += off["pop"] * 1e6
            for r, v in parse_res(off["res"]).items():
                t["res"][r] += v
        n["civ"] = n["industry"] = int(t["civ"] + 1e-6)
        n["mil"] = n["mil_factory"] = int(t["mil"] + 1e-6)
        n["dockyards"] = int(t["dock"] + 1e-6)
        n["res_prod"] = {r: int(v) for r, v in t["res"].items()}
        n["population"] = int(t["pop"])
        lv = autonomy_level(n) if n.get("overlord") is not None else None
        recruitable = int(t["pop"] * manpower_rate(n) * (1 + (lv["conscription"] if lv else 0.0))) if n["is_alive"] else 0
        n["manpower"] = max(0, n.get("manpower", 0) + recruitable - n.get("mp_base", recruitable))
        n["mp_base"] = recruitable
    for n in NATIONS:   # puppets: their autonomy level decides what goes to the overlord (HOI4)
        o = n.get("overlord")
        n["res_sent"] = n["civ_to_overlord"] = n["mil_to_overlord"] = 0
        if o is not None and n["is_alive"] and NATIONS[o]["is_alive"]:
            ov, lv = NATIONS[o], autonomy_level(n)
            share = 0.5 * lv["trade"]
            for r, v in n["res_prod"].items():
                k = int(v * share)
                ov["res_prod"][r] = ov["res_prod"].get(r, 0) + k
                n["res_prod"][r] = v - k
                n["res_sent"] += k
            c, m = int(n["civ"] * lv["civ"]), int(n["mil"] * lv["mil"])
            ov["civ"] = ov["industry"] = ov["civ"] + c
            ov["mil"] = ov["mil_factory"] = ov["mil"] + m
            n["civ"] = n["industry"] = n["civ"] - c
            n["mil"] = n["mil_factory"] = n["mil"] - m
            n["civ_to_overlord"], n["mil_to_overlord"] = c, m


def fmt_men(v):
    v = int(v)
    if abs(v) >= 1_000_000:
        return f"{v / 1e6:.2f}M"
    if abs(v) >= 10_000:
        return f"{v / 1e3:.0f}K"
    if abs(v) >= 1000:
        return f"{v / 1e3:.1f}K"
    return str(v)


# ---- construction (civilian factories) ----

def consumer_goods(n):
    """Civilian factories kept busy making consumer goods (HOI4: a share of all factories, set by the economy law)."""
    return min(n.get("civ", 0), math.ceil((n.get("civ", 0) + n.get("mil", 0)) * ECONOMY_LAWS[n["laws"]["economy"]]["consumer"]))


def civ_budget(n):
    """(total, consumer goods, trade, free for construction) civilian factories."""
    total = n.get("civ", 0)
    cg = consumer_goods(n)
    trade = min(n.get("trade_civs", 0), total - cg)
    return total, cg, trade, max(0, total - cg - trade)


def build_speed(n):
    return CIV_OUTPUT * (1.0 + n.get("output_bonus", 0.0)) * (1.25 if "captain" in n.get("advisors", []) else 1.0) \
        * ECONOMY_LAWS[n["laws"]["economy"]].get("build", 1.0)


def pending_in(n, s, kind=None):
    return sum(1 for p in n.get("construction", []) if p["state"] == s["id"]
               and (p["kind"] == kind if kind else BUILDINGS[p["kind"]].get("slot")))


def build_block(n, kind, s):
    """Why we can't start this building in state s (None = we can)."""
    b = BUILDINGS[kind]
    if s["controller"] != n["id"]:
        return "We don't control this state"
    if b.get("coastal") and not s["coastal"]:
        return "Dockyards need a coast"
    if b.get("slot") and s["slots"] - used_slots(s) - pending_in(n, s) <= 0:
        return f"No free building slots ({s['slots']} used)"
    if b.get("max") and s.get(kind, 0) + pending_in(n, s, kind) >= b["max"]:
        return f"Already level {b['max']}"
    if b.get("tech") and b["tech"] not in n.get("tech_unlocks", set()):
        return "Needs Radar research"
    return None


def queue_building(n, kind, s):
    why = build_block(n, kind, s)
    if why:
        return why
    n.setdefault("construction", []).append({"kind": kind, "state": s["id"], "progress": 0.0,
                                              "cost": float(BUILDINGS[kind]["cost"]), "civs": 0})
    return None


def finish_building(n, kind, s):
    s[kind] += 1
    if BUILDINGS[kind].get("slot"):
        s["slots"] = max(s["slots"], used_slots(s))


def construction_day(n):
    """Free civilian factories work the queue from the top, at most 15 on one project. Returns finished
    projects as (kind, state)."""
    free = civ_budget(n)[3]
    speed = build_speed(n)
    done = []
    for p in n.get("construction", []):
        s = STATES[p["state"]]
        p["civs"] = 0
        if free <= 0 or s["controller"] != n["id"]:
            continue
        k = min(MAX_CIVS_PER_PROJECT, free)
        free -= k
        p["civs"] = k
        p["progress"] += k * speed * (0.8 + 0.1 * s["infra"])
        if p["progress"] >= p["cost"]:
            done.append(p)
    for p in done:
        n["construction"].remove(p)
        finish_building(n, p["kind"], STATES[p["state"]])
    return [(p["kind"], STATES[p["state"]]) for p in done]


def project_eta(n, p):
    s = STATES[p["state"]]
    rate = p.get("civs", 0) * build_speed(n) * (0.8 + 0.1 * s["infra"])
    return (p["cost"] - p["progress"]) / rate if rate > 0 else None


def add_factories(n, kind, k):
    """A focus or decision adds factories: into our states with free slots (biggest first), opening a slot
    when there is none, like HOI4's focus rewards."""
    own = [s for s in STATES if s["owner"] == n["id"] and s["controller"] == n["id"]] or \
          [s for s in STATES if s["controller"] == n["id"]]
    if kind == "dock":
        own = [s for s in own if s["coastal"]] or own
    if not own:
        return 0
    added = 0
    for _ in range(k):
        s = max(own, key=lambda s: (s["slots"] - used_slots(s) > 0, s["infra"], s["pop"]))
        if s["slots"] - used_slots(s) <= 0:
            s["slots"] += 1
        s[kind] += 1
        added += 1
    return added


def add_infrastructure(n, k):
    own = sorted((s for s in STATES if s["owner"] == n["id"] and s["controller"] == n["id"] and s["infra"] < 5),
                 key=lambda s: (s["infra"], -s["pop"]))
    for s in own[:k]:
        s["infra"] += 1


def ai_construction(n, day):
    """AI: keep the civilian factories busy - civilian factories first in peacetime, then arms."""
    if not n.get("civ"):
        return
    q = n.setdefault("construction", [])
    free = civ_budget(n)[3]
    while len(q) < max(1, (free + MAX_CIVS_PER_PROJECT - 1) // MAX_CIVS_PER_PROJECT):
        war = bool(n["at_war_with"])
        if war or day > 900:
            kind = "mil" if random.random() < 0.8 else "civ"
        elif n["major"]:
            kind = "civ" if day < 600 or random.random() < 0.4 else "mil"
        else:
            kind = "civ" if random.random() < 0.6 else "mil"
        if n["res_prod"].get("oil", 0) < 5 and n["major"] and random.random() < 0.08:
            kind = "refinery"
        if n.get("dockyards") and n["major"] and not war and random.random() < 0.1:
            kind = "dock"
        if random.random() < (0.08 if war else 0.04):
            kind = "air_base" if random.random() < 0.6 else "aa"
            if "radar" in n.get("tech_unlocks", ()) and random.random() < 0.3:
                kind = "radar"
        own = [s for s in STATES if s["owner"] == n["id"] and build_block(n, kind, s) is None]
        if not own:
            own = [s for s in STATES if s["owner"] == n["id"] and build_block(n, "infra", s) is None]
            kind = "infra"
        if not own:
            return
        s = max(own, key=lambda s: ai_build_score(n, kind, s))
        queue_building(n, kind, s)


# ---- production (military factories) and resources ----

def resource_need(n):
    need = {r: 0 for r in RESOURCES}
    for line in n.get("lines", []):
        for r, v in equip_res(n, line["eq"]).items():
            need[r] += v * line["f"]
    return need


def trade_day(n):
    """Buy what our production lines lack on the world market: one civilian factory per 8 units (HOI4),
    at most half the factories not making consumer goods. Sunk convoys cut what arrives."""
    need = resource_need(n)
    have = n.get("res_prod", {})
    room = max(0, n.get("civ", 0) - consumer_goods(n)) // 2
    civs, imports = 0, {}
    for r in RESOURCES:
        short = need[r] - have.get(r, 0)
        if short <= 0 or civs >= room:
            continue
        k = min(room - civs, math.ceil(short / IMPORT_PER_CIV))
        civs += k
        imports[r] = int(min(short, k * IMPORT_PER_CIV) * n.get("trade", 1.0))
    n["trade_civs"], n["res_import"] = civs, imports


def trim_lines(n):
    """Lost military factories leave the newest lines first."""
    over = sum(line["f"] for line in n.get("lines", [])) - n.get("mil", 0)
    for line in reversed(n.get("lines", [])):
        if over <= 0:
            break
        cut = min(over, line["f"])
        line["f"] -= cut
        over -= cut


def line_output(n, line, ratio=None):
    """Equipment a production line turns out per day."""
    if ratio is None:
        ratio = resource_ratio(n)
    rf = min((ratio[r] for r in equip_res(n, line["eq"])), default=1.0)
    mult = production_multiplier(n) * (1.0 + n.get("output_bonus", 0.0))
    return line["f"] * MIL_OUTPUT * line["eff"] * mult * max(0.25, rf) / equip_cost(n, line["eq"])


def resource_ratio(n):
    need = resource_need(n)
    out = {}
    for r in RESOURCES:
        have = n.get("res_prod", {}).get(r, 0) + n.get("res_import", {}).get(r, 0)
        out[r] = 1.0 if need[r] <= 0 else min(1.0, have / need[r])
    return out


def production_day(n):
    trim_lines(n)
    ratio = resource_ratio(n)
    cap = EFFICIENCY_CAP + n.get("eff_bonus", 0.0)
    for line in n.get("lines", []):
        out = line_output(n, line, ratio) if line["f"] else 0.0
        line["daily"] = out
        line["acc"] = line.get("acc", 0.0) + out
        k = int(line["acc"])
        line["acc"] -= k
        if k and EQUIPMENT[line["eq"]].get("air"):   # new planes are the generation we build now
            fam, old = line["eq"], n["stockpile"].get(line["eq"], 0)
            g = n.get("air_tech", {}).get(fam, 0)
            n.setdefault("stock_gen", {})[fam] = (n["stock_gen"].get(fam, g) * old + g * k) / (old + k)
        n["stockpile"][line["eq"]] = n["stockpile"].get(line["eq"], 0) + k
        if line["f"]:
            line["eff"] = min(cap, line["eff"] + 0.004 * cap * cap / max(0.05, line["eff"]))


def set_line_shares(n, shares, eff=START_EFFICIENCY):
    """Spread the military factories over production lines by share, keeping existing lines' efficiency."""
    total = n.get("mil", 0)
    keys = [k for k in shares if equipment_unlocked(n, k)]
    weights = sum(shares[k] for k in keys) or 1.0
    raw = {k: total * shares[k] / weights for k in keys}
    got = {k: int(v) for k, v in raw.items()}
    for k in sorted(keys, key=lambda k: raw[k] - got[k], reverse=True)[:total - sum(got.values())]:
        got[k] += 1
    lines = {line["eq"]: line for line in n.setdefault("lines", [])}
    new = []
    for k in keys:
        f = got[k]
        while f > 0:
            part = min(MAX_FACTORIES_PER_LINE, f)
            line = lines.pop(k, None) or {"eq": k, "f": 0, "eff": eff, "acc": 0.0}
            line["f"] = part
            new.append(line)
            f -= part
    n["lines"] = new


def equipment_unlocked(n, key):
    if EQUIPMENT[key].get("air"):
        return n.get("air_tech", {}).get(key, -1) >= 0
    need = EQUIPMENT[key].get("tech")
    return not need or need in n.get("tech_unlocks", set())


def nation_summary_1936(name):
    """'38 divisions, 32 civ / 28 mil factories' from the 1936 tables (for the nation picker)."""
    rows = [r for r in STATES_1936 if r[0] == name]
    if not rows:
        d = next((d for d in ALL_NATIONS_DATA if d["name"] == name), {"ind": 0})
        return f"({d['ind']} factories)"
    off = STATE_OFFMAP.get(name, {})
    civ = sum(r[5] for r in rows) + off.get("civ", 0)
    mil = sum(r[6] for r in rows) + off.get("mil", 0)
    divs = sum(START_OOB.get(name, {}).values())
    return f"({divs} divisions, {civ} civ / {mil} mil factories, {len(rows)} states)"


def init_economy(units, political_map):
    """After the 1936 armies are placed: manpower, stockpiles and production lines for every country."""
    for n in NATIONS:
        n.setdefault("construction", [])
        n.setdefault("tech_unlocks", set())
        n["output_bonus"] = n.get("output_bonus", 0.0)
        n["mp_base"] = 0
        n["manpower"] = 0
    update_industry(political_map)
    fielded = {}
    for u in units:
        t = TEMPLATE_BY_KEY[u.key]
        f = fielded.setdefault(u.nation_id, {"mp": 0})
        f["mp"] += t["man_cost"]
        for k, v in t["eq"].items():
            f[k] = f.get(k, 0) + v
    for n in NATIONS:
        f = fielded.get(n["id"], {"mp": 0})
        n["manpower"] = max(n["mp_base"] // 10, n["mp_base"] - f["mp"])
        n["stockpile"] = {k: int(f.get(k, 0) * 0.25) for k in EQUIPMENT}
        n["stockpile"]["inf_eq"] += 1000 if n["major"] else 300
        set_line_shares(n, LINE_SHARES["major" if n["major"] else "minor"], eff=0.35)
        n["start_divs"] = sum(1 for u in units if u.nation_id == n["id"])
        trade_day(n)


def ai_production(n):
    """AI: rebalance its lines to its army's needs (keeps efficiency of lines that stay)."""
    shares = dict(LINE_SHARES["major" if n["major"] else "minor"])
    if n["major"] and equipment_unlocked(n, "medium_tank"):
        shares["medium_tank"] = shares.pop("light_tank", 0.16)
    if n["major"] and best_gen(n, "strat_bomber") >= 1 and nation_key(n) in ("British Empire", "German Reich", "Soviet Union", "United States"):
        shares["strat_bomber"] = 0.03
        shares["inf_eq"] -= 0.03
    if best_gen(n, "heavy_fighter") >= 1:
        shares["heavy_fighter"] = 0.02
        shares["fighter"] -= 0.02
    set_line_shares(n, shares)


