# Nations with land on the 1936 map (the USA and Japan are off-map powers there)
HISTORICAL_PLAYABLE = [d for d in ALL_NATIONS_DATA if any(d["char"] in row for row in HISTORICAL_BORDERS_RAW)]
UNCLAIMED_REGIONS = {"Albania": "q"}  # neutral land a focus can occupy
STARTING_GUARANTEES = [("French Republic", "Belgium"), ("French Republic", "Czechoslovakia")]  # in place on day 1 (France's alliances)
GUARANTEE_TENSION = 30.0  # world tension at which guarantees open up
WT_DECAY_PER_DAY = 0.03   # world tension fades slowly between crises (focuses take their full HOI4 time)
EXPANSION_TENSION = {"annex": 10.0, "border_claims": 8.0, "take_unclaimed": 5.0}  # world tension from taking land by focus


def guarantee_limit(world_tension):
    """How many countries a democratic major will guarantee: more as world tension rises."""
    return 0 if world_tension < GUARANTEE_TENSION else 2 if world_tension < 50 else 3 if world_tension < 70 else 4
TERRAIN_WORLD = {"p": 2, "u": 2, "d": 2, "f": 1, "h": 1, "s": 1, "m": 3}  # rough terrain is slower to cross

def generate_historical_world():
    """The 1936 map: land, terrain and borders straight from the HISTORICAL_* grids."""
    world = [[0 for _ in range(WORLD_WIDTH)] for _ in range(WORLD_HEIGHT)]
    for y, row in enumerate(HISTORICAL_TERRAIN_RAW[:WORLD_HEIGHT]):
        for x, ch in enumerate(row[:WORLD_WIDTH]):
            world[y][x] = TERRAIN_WORLD.get(ch, 0)
    political = generate_historical_nations(world)
    return world, political


CITY_NAMES = {}  # (x, y) -> city name, filled in for the historical map
CITY_SIZES = {}  # (x, y) -> "capital" / "medium" / "small"
CITY_VALUE = {"capital": 3, "medium": 2, "small": 1}  # weight toward capitulation


def generate_historical_nations(world_map):
    """Lay out the 1936 borders and cities from HISTORICAL_BORDERS_RAW / HISTORICAL_CITIES."""
    political_map = [[-1 for _ in range(WORLD_WIDTH)] for _ in range(WORLD_HEIGHT)]
    char_to_name = {d["char"]: d["name"] for d in ALL_NATIONS_DATA}
    name_to_id = {n["name"].replace(" (YOU)", ""): n["id"] for n in NATIONS}
    for y, row in enumerate(HISTORICAL_BORDERS_RAW[:WORLD_HEIGHT]):
        for x, ch in enumerate(row[:WORLD_WIDTH]):
            n_id = name_to_id.get(char_to_name.get(ch))
            if n_id is not None and world_map[y][x] >= 1:
                political_map[y][x] = n_id

    # Nations with no land here (USA, Japan) get no cities and stay off-map
    CITY_NAMES.clear()
    CITY_SIZES.clear()
    for n in NATIONS:
        owned = []
        for city_name, (cx, cy), size in HISTORICAL_CITIES.get(n["name"].replace(" (YOU)", ""), []):
            if political_map[cy][cx] != n["id"]:
                # Coastal smoothing can sink a tile; move the city to the nearest tile still owned
                owned = owned or [(x, y) for y in range(WORLD_HEIGHT) for x in range(WORLD_WIDTH) if political_map[y][x] == n["id"]]
                if not owned:
                    continue
                cx, cy = min(owned, key=lambda t: (t[0] - cx) ** 2 + (t[1] - cy) ** 2)
            if (cx, cy) not in n["cities"]:
                n["cities"].append((cx, cy))
                CITY_NAMES[(cx, cy)] = city_name
                CITY_SIZES[(cx, cy)] = size
    return political_map


def generate_nations(world_map):
    political_map = [[-1 for _ in range(WORLD_WIDTH)]
                     for _ in range(WORLD_HEIGHT)]
    land_tiles = [(x, y) for y in range(WORLD_HEIGHT)
                  for x in range(WORLD_WIDTH) if world_map[y][x] >= 2]

    if not land_tiles:
        land_tiles = [(WORLD_WIDTH//2, WORLD_HEIGHT//2)]  # Ultimate fallback
        world_map[WORLD_HEIGHT//2][WORLD_WIDTH//2] = 2

    # Safely select capitals up to the available number of land tiles
    num_to_spawn = min(len(NATIONS), len(land_tiles))
    capitals = random.sample(land_tiles, num_to_spawn)
    queue = []

    for i, cap in enumerate(capitals):
        political_map[cap[1]][cap[0]] = i
        NATIONS[i]["cities"].append(cap)
        queue.append((cap[0], cap[1], i))

    while queue:
        cx, cy, nation_id = queue.pop(0)
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = cx + dx, cy + dy
            if 0 <= nx < WORLD_WIDTH and 0 <= ny < WORLD_HEIGHT and world_map[ny][nx] >= 2 and political_map[ny][nx] == -1:
                political_map[ny][nx] = nation_id
                queue.append((nx, ny, nation_id))

    for y in range(WORLD_HEIGHT):
        for x in range(WORLD_WIDTH):
            if world_map[y][x] >= 2 and political_map[y][x] == -1:
                world_map[y][x] = 1

    for i in range(len(NATIONS)):
        nation_territory = [(x, y) for y in range(WORLD_HEIGHT)
                            for x in range(WORLD_WIDTH) if political_map[y][x] == i]
        if len(nation_territory) > 10:
            extra_cities = random.sample(
                nation_territory, min(4, len(nation_territory) // 10))
            for c in extra_cities:
                if c not in NATIONS[i]["cities"]:
                    NATIONS[i]["cities"].append(c)

    # Ensure every single nation has at least one city so game never crashes
    for i in range(len(NATIONS)):
        if not NATIONS[i]["cities"]:
            unclaimed = [(x, y) for y in range(WORLD_HEIGHT) for x in range(WORLD_WIDTH) if world_map[y][x] >= 2 and political_map[y][x] == -1]
            cap = random.choice(unclaimed if unclaimed else land_tiles)
            political_map[cap[1]][cap[0]] = i
            NATIONS[i]["cities"].append(cap)

    return political_map


def get_direction_arrow(dx, dy):
    """Returns 8-way arrow character based on directional vector (dx, dy)."""
    if dx == 0 and dy == 0:
        return "►"
    angle = math.atan2(dy, dx)
    deg = math.degrees(angle)
    if -22.5 <= deg < 22.5:
        return "►"
    elif 22.5 <= deg < 67.5:
        return "↘"
    elif 67.5 <= deg < 112.5:
        return "▼"
    elif 112.5 <= deg < 157.5:
        return "↙"
    elif deg >= 157.5 or deg < -157.5:
        return "◄"
    elif -157.5 <= deg < -112.5:
        return "↖"
    elif -112.5 <= deg < -67.5:
        return "▲"
    elif -67.5 <= deg < -22.5:
        return "↗"
    return "►"


def bresenham_line(x0, y0, x1, y1):
    """Generates coordinate path from (x0, y0) to (x1, y1)."""
    points = []
    dx = abs(x1 - x0)
    dy = abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx - dy
    curr_x, curr_y = x0, y0
    while True:
        points.append((curr_x, curr_y))
        if curr_x == x1 and curr_y == y1:
            break
        e2 = 2 * err
        if e2 > -dy:
            err -= dy
            curr_x += sx
        if e2 < dx:
            err += dx
            curr_y += sy
    return points


def safe_draw(stdscr, y, x, text, color=0):
    try:
        term_h, term_w = stdscr.getmaxyx()
        y, x = int(y), int(x)
        if y < 0 or y >= term_h - 1:
            return
        if x < 0:
            if abs(x) >= len(text):
                return
            text = text[-x:]
            x = 0
        if x + len(text) >= term_w:
            text = text[:max(0, term_w - x - 1)]
        if text:
            stdscr.addstr(y, x, text, color)
    except curses.error:
        pass


def center_camera(cam_x, cam_y, target_x, target_y, vw, vh):
    return max(0, min(WORLD_WIDTH - vw, target_x - vw // 2)), max(0, min(WORLD_HEIGHT - vh, target_y - vh // 2))


def annex_nation(victim, winner, political_map, units):
    """Peacefully absorb a whole country (e.g. the Anschluss): land, divisions, manpower, equipment."""
    for y in range(WORLD_HEIGHT):
        for x in range(WORLD_WIDTH):
            if political_map[y][x] == victim["id"]:
                political_map[y][x] = winner["id"]
    for u in units:
        if u.nation_id == victim["id"]:
            u.nation_id, u.army_id, u.order, u.is_guarding = winner["id"], None, None, False
            u.path, u.target_x, u.target_y = [], None, None
    for f in FLEETS:
        if f.nation_id == victim["id"]:
            f.nation_id = winner["id"]
    winner["convoys"] = winner.get("convoys", 0) + victim.get("convoys", 0)
    for item, amount in victim["stockpile"].items():
        winner["stockpile"][item] = winner["stockpile"].get(item, 0) + amount
    for s in STATES:
        if s["owner"] == victim["id"]:
            s["owner"] = winner["id"]
            s["resist"], s["comply"], s["occ_by"] = 0.0, 0.0, None
    victim["is_alive"] = False
    victim["capitulated"] = False
    free_subjects(victim)
    transfer_air_force(victim, winner)
    victim["at_war_with"].clear()
    for other in NATIONS:
        other["at_war_with"].discard(victim["id"])
        other["wargoals"].discard(victim["id"])
        other["justifying"].pop(victim["id"], None)
        other["guaranteeing"].discard(victim["id"])


def take_border_land(victim, winner, political_map):
    """Give the winner every tile of the victim that touches the winner's land (e.g. the Sudetenland).
    The victim keeps its cities, so this alone never makes it capitulate."""
    claim = [(x, y) for y in range(WORLD_HEIGHT) for x in range(WORLD_WIDTH)
             if political_map[y][x] == victim["id"] and (x, y) not in victim["cities"] and any(
                 0 <= x + dx < WORLD_WIDTH and 0 <= y + dy < WORLD_HEIGHT and political_map[y + dy][x + dx] == winner["id"]
                 for dx in (-1, 0, 1) for dy in (-1, 0, 1))]
    for x, y in claim:
        political_map[y][x] = winner["id"]
    for s in STATES:   # a state that is now mostly the winner's is the winner's
        if s["owner"] == victim["id"] and 2 * sum(1 for x, y in s["tiles"] if political_map[y][x] == winner["id"]) > len(s["tiles"]):
            s["owner"] = winner["id"]
    return len(claim)


