def place_start_armies(n, keys, political_map, world_map, units, next_id, city_tiles):
    """Spread a country's 1936 divisions over its states (the biggest first), a division per tile
    where there is room, next to each state's main town."""
    own = sorted((s for s in STATES if s["core"] == n["id"] and s["controller"] == n["id"]), key=lambda s: -s["pop"])
    taken = {}
    made = []
    for i, k in enumerate(keys):
        if own:
            s = own[i % len(own)]
            cx, cy = s["x"], s["y"]
            spots = [t for t in s["tiles"] if political_map[t[1]][t[0]] == n["id"]] or [(cx, cy)]
        else:
            cx, cy = n["cities"][0]
            spots = [(x, y) for y in range(max(0, cy - 4), min(WORLD_HEIGHT, cy + 5)) for x in range(max(0, cx - 4), min(WORLD_WIDTH, cx + 5))
                     if world_map[y][x] and political_map[y][x] == n["id"]] or [(cx, cy)]
        x, y = min(spots, key=lambda t: (taken.get(t, 0), t in city_tiles, (t[0] - cx) ** 2 + ((t[1] - cy) * 2) ** 2))
        taken[(x, y)] = taken.get((x, y), 0) + 1
        made.append(Division(next_id + i, n["id"], x, y, TEMPLATE_BY_KEY[k]))
    units.extend(made)
    return next_id + len(keys)


def land_upkeep_hour(units):
    """Organisation comes back out of combat; divisions that stay put dig in."""
    for u in units:
        if u.sea is not None:
            continue
        if u.in_battle:
            u.in_battle -= 1
        else:
            u.org = min(u.max_org, u.org + u.max_org * (0.01 if u.moved else 0.025))
        if u.moved:
            u.entrench = 0.0
        elif not u.in_battle:
            u.entrench = min(5.0, u.entrench + TEMPLATE_BY_KEY[u.key].get("dig", 1.0) / 24)
        if u.retreat_hours:
            u.retreat_hours -= 1
        if u.landing:
            u.landing -= 1
        u.moved = False


def reinforce_divisions(units, political_map):
    """Once a day, divisions out of combat on friendly soil refill up to 10% of their strength from
    the manpower pool and the equipment stockpile."""
    for u in units:
        if u.sea is not None or u.hp >= u.max_hp or u.in_battle:
            continue
        n = NATIONS[u.nation_id]
        if political_map[u.y][u.x] not in friends_of(n):
            continue
        t = TEMPLATE_BY_KEY[u.key]
        frac = min(u.max_hp - u.hp, u.max_hp * 0.1 * t.get("reinforce", 1.0)) / u.max_hp
        if t["man_cost"] * frac > n["manpower"]:
            frac = n["manpower"] / t["man_cost"]
        for k, v in t["eq"].items():
            if v * frac > n["stockpile"].get(k, 0):
                frac = n["stockpile"].get(k, 0) / v
        if frac <= 0:
            continue
        n["manpower"] -= int(round(t["man_cost"] * frac))
        for k, v in t["eq"].items():
            n["stockpile"][k] = n["stockpile"].get(k, 0) - int(round(v * frac))
        u.hp = min(u.max_hp, u.hp + u.max_hp * frac)


def can_afford(n, t):
    return n["manpower"] >= t["man_cost"] and all(n["stockpile"].get(k, 0) >= v for k, v in t["eq"].items())


def pay_for(n, t):
    n["manpower"] -= t["man_cost"]
    for k, v in t["eq"].items():
        n["stockpile"][k] = n["stockpile"].get(k, 0) - v


def ai_can_afford(n, t):
    """The AI only raises a division when it keeps enough equipment back to refill the ones it has."""
    spare = 3 if n["at_war_with"] else 2
    return n["manpower"] >= t["man_cost"] * 2 and all(n["stockpile"].get(k, 0) >= v * spare for k, v in t["eq"].items())


def ai_pick_template(n):
    """AI recruitment: some armour and motorised for the big powers, mountain troops for mountain countries."""
    roll = random.random()
    order = []
    if n["major"] and roll < 0.25:
        order.append("arm")
    if n["major"] and roll < 0.45:
        order.append("mot")
    if nation_key(n) in ("Switzerland", "Kingdom of Italy", "Austria", "Yugoslavia", "Greece") and roll > 0.8:
        order.append("mtn")
    order += ["inf2", "inf", "cav"]
    for key in order:
        t = best_template(n, key)
        if t and ai_can_afford(n, t):
            return t
    return None


