def guarantor_of(n):
    """The major most likely to speak for n: Britain, then France, then any guarantor."""
    ps = protectors(n)
    for key in ("British Empire", "French Republic"):
        g = next((p for p in ps if nation_key(p) == key), None)
        if g:
            return g
    return ps[0] if ps else None


def cede_sudeten(c, cz, ger, news="munich.news"):
    got = cede_states(cz, ger, SUDETEN_STATES, c["pm"], c["units"])
    if not got:
        take_border_land(cz, ger, c["pm"])
    add_wt(EXPANSION_TENSION["border_claims"])
    ger["tension_generated"] += EXPANSION_TENSION["border_claims"]
    EVENT_FLAGS.add("sudetenland")
    fire_news(news, ger, {"actors": [ger["id"]], "victims": [cz["id"]]})


