def fate_cz_accept(c):
    cz, ger = c["n"], c["frm"]
    hun = alive("Hungary")
    if hun and hun["id"] not in ger["at_war_with"]:
        cede_states(cz, hun, ["Carpathian Ruthenia", "Eastern Slovakia"], c["pm"], c["units"])
    peaceful_annex(cz, ger, c["pm"], c["units"])
    add_wt(EXPANSION_TENSION["annex"])
    ger["tension_generated"] += EXPANSION_TENSION["annex"]
    fire_news("prague.news", ger, {"actors": [ger["id"]], "victims": [cz["id"]]})
    # Prague opens Western eyes: Britain and France promise to defend the next victims
    for gk in ("British Empire", "French Republic"):
        g = alive(gk)
        for vk in ("Second Polish Republic", "Romania", "Greece"):
            v = alive(vk)
            if g and v and not v["faction"] and v["id"] not in g["guaranteeing"] and v["id"] not in g["at_war_with"]:
                g["guaranteeing"].add(v["id"])
                v["guaranteed_by"].add(g["id"])
                if v["id"] == 0:
                    fire_event("dip.guarantee", 0, g, delay=1)
    if alive("Second Polish Republic"):
        fire_news("guarantee.news", alive("British Empire"), {"actors": [i for i in (nation_id_of("British Empire"), nation_id_of("French Republic")) if i is not None],
                                                               "victims": []})


