DOCTRINE_TRACKS = (("fighter", "Fighter Aircraft"), ("strike", "Strike Aircraft"), ("medium", "Medium Aircraft"), ("heavy", "Heavy Aircraft"))
AIR_DOCTRINE_COST = 100     # air experience (HOI4)
MILESTONE_MASTERY = 60      # mastery a track needs for its milestone
MISSION_CODE = {"AIR_SUPERIORITY": "AS", "INTERCEPT": "INT", "CAS": "CAS", "STRAT_BOMB": "BOMB", "NAVAL_STRIKE": "NAV",
                "PORT_STRIKE": "PORT", "NAVAL_PATROL": "PAT", "TRAINING": "TRN", "IDLE": "-"}
AIR_SPOTTING = {"AIR_SUPERIORITY": 0.5, "INTERCEPT": 0.25, "NAVAL_STRIKE": 0.5, "NAVAL_PATROL": 1.5}   # HOI4 AIR_MISSION_SPOTTING_FACTORS
SEA_AIR_DOMINANCE = {"NAVAL_PATROL": 2.0, "NAVAL_STRIKE": 0.8}   # naval dominance per plane over a sea zone
GLYPH_PLANE, GLYPH_AIRBASE = "\uf072", "\U000f001d"


class AirWing:
    __slots__ = ("id", "nation_id", "family", "gen", "planes", "size", "base", "zone", "mission", "xp", "ramp", "name",
                 "ace", "kills", "losses", "today", "seen_zone")

    def __init__(self, nation_id, family, gen, planes, base, name=None, size=None):
        self.id = AIR["next_id"]
        AIR["next_id"] += 1
        self.nation_id, self.family, self.gen = nation_id, family, float(gen)
        self.planes = int(planes)
        self.size = int(size or max(10, planes))
        self.base, self.zone, self.mission = base, None, "IDLE"
        self.xp, self.ramp = 120.0, 1.0
        self.name = name or wing_name(NATIONS[nation_id], family)
        self.ace = None
        self.kills, self.losses = 0, 0
        self.today = {"kills": 0, "lost": 0, "dmg": 0.0}
        self.seen_zone = None


# ---- planes ----

PLANE_STATS_CACHE = {}


def plane_stats(family, gen):
    """HOI4 stats of a plane family at a (possibly mixed, fractional) generation: rng spd agi atk dfn gnd bomb nav navt sup rel cost.
    A fresh dict the caller may change."""
    st = PLANE_STATS_CACHE.get((family, gen))
    if st is None:
        if len(PLANE_STATS_CACHE) > 5000:
            PLANE_STATS_CACHE.clear()
        st = PLANE_STATS_CACHE[(family, gen)] = _plane_stats(family, gen)
    return dict(st)


def plane_stat(family, gen, key):
    """One stat of a plane (no copy)."""
    st = PLANE_STATS_CACHE.get((family, gen))
    if st is None:
        plane_stats(family, gen)
        st = PLANE_STATS_CACHE[(family, gen)]
    return st[key]


def _plane_stats(family, gen):
    gens = sorted(PLANE_STATS[family])
    g = max(gens[0], min(gens[-1], gen))
    lo = max(x for x in gens if x <= g)
    hi = min(x for x in gens if x >= g)
    f = 0.0 if hi == lo else (g - lo) / (hi - lo)
    a, b = PLANE_STATS[family][lo], PLANE_STATS[family][hi]
    v = [a[i] + (b[i] - a[i]) * f for i in range(len(a))]
    return {"rng": v[1], "spd": v[2], "agi": v[3], "atk": v[4], "dfn": v[5], "gnd": v[6], "bomb": v[7], "nav": v[8], "navt": v[9],
            "sup": v[10], "rel": v[11], "cost": v[12]}


def plane_name(n, family, gen):
    g = int(round(gen))
    key = f"{family}_{g}"
    return PLANE_NAMES.get(nation_key(n), {}).get(key) or PLANE_GENERIC_NAMES.get(key) or FAMILY_INFO[family][0]


def best_gen(n, family):
    return n.setdefault("air_tech", {}).get(family, -1)


def wing_name(n, family):
    cnt = n.setdefault("wing_count", {})
    k = cnt[family] = cnt.get(family, 0) + 1
    pat = WING_NAME_PATTERNS.get(nation_key(n), {}).get(family)
    roman = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV", "XV", "XVI", "XVII", "XVIII",
             "XIX", "XX"][(k - 1) % 20] + f"/{(k - 1) // 20 + 1}"
    if pat:
        return pat.format(n=k, o=ordinal(k), r=roman)
    return f"{ordinal(k)} {FAMILY_INFO[family][0][:-1] if FAMILY_INFO[family][0].endswith('s') else FAMILY_INFO[family][0]} Wing"


def aa_shield(d):
    """How much a division's own anti-air blunts the enemy's air superiority (HOI4: 0.75 * aa^1.5 / (aa^1.5 + 625))."""
    a = getattr(d, "aa", 0.0)
    if a <= 0:
        return 0.0
    x = a ** 1.5
    return 0.75 * x / (x + 625.0)


def air_research_block(n, opt, year):
    """(next plane generation, why it can't be researched yet or None) for a plane design."""
    fam = opt["family"]
    cur = best_gen(n, fam)
    nxt = next((g for g in sorted(PLANE_STATS[fam]) if g > cur), None)
    if nxt is None:
        return cur, "Fully researched"
    if year < PLANE_STATS[fam][nxt][0]:
        return nxt, f"Available from {PLANE_STATS[fam][nxt][0]}"
    if n["pp"] < opt["cost_pp"]:
        return nxt, f"Needs {opt['cost_pp']} PP"
    return nxt, None


def air_xp_level(xp):
    lvl = AIR_XP_LEVELS[0]
    for row in AIR_XP_LEVELS:
        if xp >= row[0]:
            lvl = row
    return lvl


def air_mod(n, key):
    """A doctrine effect of country n (its grand doctrine and the milestones it has unlocked)."""
    doc = n.get("air_doctrine")
    if not doc:
        return 0.0
    ms = n.get("milestones") or ()
    fx = n.get("air_fx")
    if fx is None or fx[0] != doc or fx[1] != len(ms):
        d = AIR_DOCTRINES[doc]
        tot = dict(d[2])
        for track in ms:
            for k, v in d[3][track].items():
                tot[k] = tot.get(k, 0.0) + v
        fx = n["air_fx"] = (doc, len(ms), tot)
    return fx[2].get(key, 0.0)


def wing_stats(w):
    """The wing's stats with its pilots' experience, its ace and the doctrine."""
    n = NATIONS[w.nation_id]
    st = plane_stats(w.family, w.gen)
    q = 1.0 + air_xp_level(w.xp)[2]
    st["atk"] *= q
    st["agi"] *= q
    st["gnd"] *= q
    if w.ace:
        for k, v in w.ace["fx"].items():
            st[k] = st.get(k, 0.0) * (1 + v)
    if w.family == "fighter":
        st["agi"] *= 1 + air_mod(n, "fighter_agi")
    if w.family == "heavy_fighter":
        st["agi"] *= 1 + air_mod(n, "hf_agi")
    if w.family == "cas":
        st["agi"] *= 1 + air_mod(n, "cas_agi")
    if w.family == "strat_bomber":
        st["dfn"] *= 1 + air_mod(n, "strat_def")
        st["bomb"] *= 1 + air_mod(n, "strat_bomb")
    if w.family == "tac_bomber":
        st["bomb"] *= 1 + air_mod(n, "tac_bomb")
    return st


# ---- zones, bases, range ----

def tile_km(a, b):
    return math.hypot((a[0] - b[0]) * KM_X, (a[1] - b[1]) * KM_Y)


def build_air_map(world_map, historical):
    """The air zones: HOI4's strategic regions over land (AIR_ZONE_RAW) and the sea zones over the water."""
    AIR_ZONES.clear()
    AIR_ZONE_GRID.clear()
    W, H = WORLD_WIDTH, WORLD_HEIGHT
    if historical:
        names = list(AIR_ZONE_NAMES)
        L = len(names)
        names += list(SEA_REGION_NAMES)
        for y in range(H):
            row = AIR_ZONE_RAW[y] if y < len(AIR_ZONE_RAW) else ""
            out = []
            for x in range(W):
                if world_map[y][x] == 0:
                    r = SEA_REGION[y][x] if SEA_REGION else -1
                    out.append(L + r if r >= 0 else -1)
                else:
                    ch = row[x] if x < len(row) else "."
                    out.append(AIR_ZONE_CODE.index(ch) if ch != "." and ch in AIR_ZONE_CODE else -1)
            AIR_ZONE_GRID.append(out)
    else:   # random maps: the land in blocks, the sea in its zones
        cols, rows = 5, 3
        names = [f"Air Zone {i + 1}" for i in range(cols * rows)]
        L = len(names)
        names += list(NAVY.get("region_names", []))
        for y in range(H):
            AIR_ZONE_GRID.append([((y * rows // H) * cols + x * cols // W) if world_map[y][x] else
                                  (L + SEA_REGION[y][x] if SEA_REGION and SEA_REGION[y][x] >= 0 else -1) for x in range(W)])
    # land tiles the raw grid missed take a neighbour's zone
    for _ in range(3):
        for y in range(H):
            for x in range(W):
                if world_map[y][x] and AIR_ZONE_GRID[y][x] < 0:
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1), (1, 1), (-1, -1)):
                        if 0 <= x + dx < W and 0 <= y + dy < H and AIR_ZONE_GRID[y + dy][x + dx] >= 0:
                            AIR_ZONE_GRID[y][x] = AIR_ZONE_GRID[y + dy][x + dx]
                            break
    tiles = [[] for _ in names]
    for y in range(H):
        for x in range(W):
            z = AIR_ZONE_GRID[y][x]
            if z >= 0:
                tiles[z].append((x, y))
    for z, nm in enumerate(names):
        t = tiles[z]
        zone = {"id": z, "name": nm, "sea": z >= L, "sea_index": z - L if z >= L else -1, "tiles": t, "states": [], "ports": []}
        if t:
            step = max(1, len(t) // 28)
            zone["samples"] = t[::step]
            cx, cy = sum(p[0] for p in t) / len(t), sum(p[1] for p in t) / len(t)
            zone["label"] = min(t, key=lambda p: (p[0] - cx) ** 2 + ((p[1] - cy) * 2) ** 2)
        else:
            zone["samples"], zone["label"] = [], None
        AIR_ZONES.append(zone)
    AIR["land_zones"] = L
    for s in STATES:
        cnt = {}
        for x, y in s["tiles"]:
            z = AIR_ZONE_GRID[y][x]
            cnt[z] = cnt.get(z, 0) + 1
        s["zone"] = max(cnt, key=cnt.get) if cnt else -1
        if s["zone"] >= 0:
            AIR_ZONES[s["zone"]]["states"].append(s["id"])
    for i, p in enumerate(PORTS):
        z = AIR_ZONE_GRID[p["y"]][p["x"]] if 0 <= p["y"] < H and 0 <= p["x"] < W else -1
        if z >= 0:
            AIR_ZONES[z]["ports"].append(i)


def zone_dists(base, z):
    """Sorted distances (km) from air base state `base` to the sample points of zone z."""
    key = (base, z)
    d = AIR["dist"].get(key)
    if d is None:
        s = STATES[base]
        d = AIR["dist"][key] = sorted(tile_km((s["x"], s["y"]), p) for p in AIR_ZONES[z]["samples"]) or [1e9]
    return d


def coverage(base, z, rng):
    """Share of zone z within reach of air base `base` for planes of range rng km (HOI4 mission coverage)."""
    if base is None or z is None or z < 0:
        return 0.0
    d = zone_dists(base, z)
    return bisect.bisect_right(d, rng) / len(d)


def wing_range(w):
    r = plane_stat(w.family, w.gen, "rng")
    if w.ace:
        r *= 1 + w.ace["fx"].get("rng", 0.0)
    return r


def base_capacity(s):
    return int(AIRBASE_CAPACITY * s.get("air_base", 0) * (1 - 0.5 * s.get("bomb", 0.0)))


def base_friendly(s, n):
    return s.get("air_base", 0) > 0 and s["controller"] >= 0 and s["controller"] in friends_of(n)


def own_bases(n):
    bs = AIR.get("base_states")
    if bs is None or AIR.get("base_day") != EVENT_DAY[0]:
        bs = AIR["base_states"] = [s for s in STATES if s.get("air_base", 0) > 0]
        AIR["base_day"] = EVENT_DAY[0]
    nid = n["id"]
    return [s for s in bs if s["controller"] == nid]


def best_base(n, z, rng, avoid=None, near=None):
    """Our air base that reaches zone z best (most coverage, then free room, then nearest the given spot)."""
    best, key = None, None
    for s in own_bases(n):
        cov = coverage(s["id"], z, rng) if z is not None else 1.0
        if z is not None and cov <= 0:
            continue
        room = base_capacity(s) - AIR["base_load"].get(s["id"], 0)
        k = (round(cov, 1), room > 0, -(abs(s["x"] - near[0]) + abs(s["y"] - near[1])) if near else s.get("air_base", 0))
        if key is None or k > key:
            best, key = s, k
    return best


def radar_level(z, n):
    """The best radar station of n's side that reaches zone z (HOI4: 250 km, +50 km a level)."""
    rs = AIR.get("radars")
    if rs is None or AIR.get("radar_day") != EVENT_DAY[0]:
        rs = AIR["radars"] = [s for s in STATES if s.get("radar")]
        AIR["radar_day"] = EVENT_DAY[0]
    if not rs:
        return 0
    fr = friends_of(n)
    return max((s["radar"] for s in rs if s["controller"] in fr and zone_dists(s["id"], z)[0] <= 250 + 50 * s["radar"]), default=0)


def wing_eff(w):
    """Mission efficiency: how much of the zone is in reach, crowding at the base, getting used to a new zone."""
    if w.zone is None or w.base is None:
        return 0.0
    s = STATES[w.base]
    cov = coverage(w.base, w.zone, wing_range(w))
    cap = max(1, base_capacity(s))
    load = AIR["base_load"].get(w.base, 0)
    crowd = 1.0 if load <= cap else max(0.1, 1 - 2 * (load - cap) / cap)   # HOI4 CAPACITY_PENALTY = 2
    return cov * crowd * w.ramp


def refresh_base_load():
    load = {}
    for w in AIR["wings"]:
        if w.base is not None:
            load[w.base] = load.get(w.base, 0) + w.planes
    AIR["base_load"] = load


# ---- the 1936 air forces ----

def reset_air():
    AIR.update({"wings": [], "next_id": 1, "sup": {}, "pen": {}, "spd": {}, "support": {}, "log": [], "report": {}, "dist": {},
                "seen": {}, "bombed": {}, "fights": {}, "base_load": {}, "round": 0, "cause": {}, "sunk": {},
       "base_states": None, "base_day": None, "sea_air": {}})


def init_air(world_map, political_map, historical):
    """Air zones, air bases and anti-air, everyone's air technology and the 1936 air forces at their bases."""
    reset_air()
    build_air_map(world_map, historical)
    by_name = {}
    for s in STATES:
        by_name.setdefault(s["name"], s)
        s["air_base"] = AIR_BASES_1936.get(s["name"], 0) if historical else 0
        s["aa"] = STATE_AA_1936.get(s["name"], 0) if historical else 0
        s["radar"] = 0
        s["bomb"] = 0.0
    for n in NATIONS:
        key = nation_key(n)
        if historical:
            n["air_tech"] = dict(AIR_TECH_1936.get(key, {"fighter": 0}))
        else:
            n["air_tech"] = {"fighter": 1, "cas": 1, "tac_bomber": 1} if n["major"] else {"fighter": 0}
        n["stock_gen"] = {f: max(0, g) for f, g in n["air_tech"].items()}
        n["air_xp"], n["air_doctrine"], n["mastery"], n["milestones"] = 0.0, None, {t: 0.0 for t, _ in DOCTRINE_TRACKS}, set()
        n["wing_count"], n["air_xp_day"] = {}, 0.0
        for f in AIR_FAMILIES:
            n["stockpile"].setdefault(f, 0)
        if not historical and n["cities"]:   # random maps: an air base at the capital and a couple of wings
            s = state_at(*n["cities"][0])
            if s:
                s["air_base"] = 5 if n["major"] else 2
                AIR["base_day"] = None
                for f in ("fighter", "cas") if n["major"] else ("fighter",):
                    if f in n["air_tech"]:
                        AIR["wings"].append(AirWing(n["id"], f, n["air_tech"][f], 100 if n["major"] else 40, s["id"]))
    if historical:
        for country, wings in AIR_OOB_1936.items():
            n = nation_by_key(country)
            if n is None:
                continue
            reserve = {}
            for state, fam, gen, planes, name in wings:
                s = by_name.get(state)
                if s is None or s["controller"] != n["id"]:
                    s = best_base(n, None, 0, near=n["cities"][0] if n["cities"] else None)
                if s is None:
                    continue
                s["air_base"] = max(1, s.get("air_base", 0))
                AIR["base_day"] = None
                AIR["wings"].append(AirWing(n["id"], fam, gen, planes, s["id"], name=name, size=max(planes, 50)))
                n["air_tech"][fam] = max(n["air_tech"].get(fam, -1), gen)
                reserve[fam] = reserve.get(fam, 0) + planes
            for fam, k in reserve.items():   # planes in the stockpile: a fifth of what flies
                n["stockpile"][fam] = n["stockpile"].get(fam, 0) + k // 5
                n["stock_gen"][fam] = max(0, n["air_tech"].get(fam, 0))
    for n in NATIONS:   # now that everyone knows its planes, the factories make some of them too
        set_line_shares(n, LINE_SHARES["major" if n["major"] else "minor"], eff=0.35)
        trade_day(n)
    refresh_base_load()


# ---- the air battle, every 4 hours ----

def at_war(a, b):
    return b in NATIONS[a]["at_war_with"]


def lose(e, k, cause):
    """Wing entry e loses k planes (expected) to: air (enemy planes), aa (guns on the ground), div_aa, ship_aa."""
    e[4] += k
    c = AIR["cause"].setdefault(e[0].nation_id, {})
    c[cause] = c.get(cause, 0.0) + k


def kill_chance(a, t):
    """HOI4-like chance that one shot of a plane with stats a downs a plane with stats t."""
    dmg = 0.2 * a["atk"]                                               # COMBAT_DAMAGE_STATS_MULTILPIER
    if t["agi"] > a["agi"]:                                            # the nimbler target dodges (up to 45%)
        dmg *= 1 - 0.45 * min(1.0, (t["agi"] - a["agi"]) / max(1.0, t["agi"]))
    else:
        dmg *= min(4.0, a["agi"] / max(1.0, t["agi"])) ** 0.25        # BIGGEST_AGILITY_FACTOR_DIFF = 4
    if a["spd"] > t["spd"]:                                            # the faster one picks its fights (up to +65%)
        dmg *= 1 + 0.65 * min(1.0, (a["spd"] - t["spd"]) / max(1.0, t["spd"]))
    return max(0.0, min(0.2, dmg / (max(1.0, t["dfn"]) * 80.0)))


def air_round(pm, units):
    """One round of the air war: every zone where planes fly."""
    AIR["round"] += 1
    refresh_base_load()
    flying = {}
    for w in AIR["wings"]:
        if w.mission in ("IDLE", "TRAINING") or w.zone is None or w.planes <= 0:
            continue
        n = NATIONS[w.nation_id]
        if not n["at_war_with"] or not n["is_alive"]:
            continue
        act = w.planes * wing_eff(w) * SORTIE
        if act >= 1:
            flying.setdefault(w.zone, []).append([w, act, wing_stats(w), 0.0, 0.0])   # wing, active, stats, kills, lost
    sup, pen, spd, support = {}, {}, {}, {}
    sea_air = {}
    for z, fl in flying.items():
        zone = AIR_ZONES[z]
        if zone["sea"]:
            for e in fl:
                k = SEA_AIR_DOMINANCE.get(e[0].mission)
                if k:
                    d = sea_air.setdefault(zone["sea_index"], {})
                    d[e[0].nation_id] = d.get(e[0].nation_id, 0.0) + e[1] * k
    AIR["sea_air"] = sea_air
    by_id = None
    for z, fl in flying.items():
        zsup = zone_superiority(z, fl)
        sup[z] = zsup
        for nid, (share, enemy_bonus) in zsup.items():
            if share < 0.5:
                pen.setdefault(z, {})[nid] = 0.35 * (1 - 2 * share) * (1 + enemy_bonus)    # ENEMY_AIR_SUPERIORITY_IMPACT
                spd.setdefault(z, {})[nid] = 0.3 * (1 - 2 * share)                         # ..._SPEED_IMPACT
        dogfight(z, fl)
        ground_aa(z, fl, pm)
        for e in fl:
            e[1] = max(0.0, e[1] - e[4])
        if any(e[0].mission == "CAS" for e in fl):
            if by_id is None:
                by_id = {u.id: u for u in units}
            close_air_support(z, fl, units, by_id, support)
        if any(e[0].mission == "STRAT_BOMB" for e in fl):
            strategic_bombing(z, fl, pm)
        if any(e[0].mission in ("NAVAL_STRIKE", "PORT_STRIKE") for e in fl):
            naval_strikes(z, fl)
        settle_losses(z, fl)
    AIR["sup"], AIR["pen"], AIR["spd"], AIR["support"] = sup, pen, spd, support


def zone_superiority(z, fl):
    """{nation: (share of the sky its side holds, the enemy's doctrine bonus)} for everyone at war with a flyer here.
    Fighters on Air Superiority count in full, interceptors a quarter (HOI4); the enemy's anti-air takes some away."""
    val = {}
    for w, act, st, _, _ in fl:
        k = 1.0 if w.mission == "AIR_SUPERIORITY" else 0.25 if w.mission == "INTERCEPT" else 0.0
        if k:
            n = NATIONS[w.nation_id]
            val[w.nation_id] = val.get(w.nation_id, 0.0) + act * st["sup"] * k * (1 + air_mod(n, "sup_eff") + air_mod(n, "sup_detect"))
    zone = AIR_ZONES[z]
    if not val:
        return {}
    for c in val:   # radar sees the enemy coming: +5% per level of the best station in range
        lvl = radar_level(z, NATIONS[c])
        if lvl:
            val[c] *= 1 + 0.05 * lvl
    flyers = set(val)
    cands = set(flyers)
    for a in flyers:
        cands |= NATIONS[a]["at_war_with"]
    out = {}
    for x in cands:
        nx = NATIONS[x]
        if not nx["is_alive"]:
            continue
        fr, foes = friends_of(nx), nx["at_war_with"]
        mine = sum(v for y, v in val.items() if y in fr or (y not in foes and NATIONS[y]["at_war_with"] & foes))
        theirs = sum(v for y, v in val.items() if y in foes)
        for sid in zone["states"]:   # anti-air guns over our own land knock out enemy superiority (5 per level)
            s = STATES[sid]
            if s.get("aa") and s["controller"] >= 0 and not at_war(x, s["controller"]) and theirs > 0:
                theirs = max(0.0, theirs - 5.0 * s["aa"])
        if mine + theirs <= 0:
            continue
        bonus = max((air_mod(NATIONS[y], "army_sup") for y in val if at_war(x, y)), default=0.0)
        out[x] = (mine / (mine + theirs), bonus)
    return out


def dogfight(z, fl):
    """Fighters on Air Superiority and Interception shoot at the enemy's planes; bombers fire back."""
    for e in fl:
        w, act, st = e[0], e[1], e[2]
        if w.family not in ("fighter", "heavy_fighter") or w.mission not in ("AIR_SUPERIORITY", "INTERCEPT"):
            continue
        foes = [t for t in fl if at_war(w.nation_id, t[0].nation_id)]
        if not foes:
            continue
        intercept = w.mission == "INTERCEPT"
        n = NATIONS[w.nation_id]
        weights = []
        for t in foes:
            fighter = t[0].family in ("fighter", "heavy_fighter")
            wt = t[1] * ((3.0 if not fighter else 1.0) if intercept else (2.0 if fighter else 1.0))
            if not fighter:   # escorts in the zone keep the interceptors off their bombers
                tn = NATIONS[t[0].nation_id]
                esc = sum(f[1] for f in fl if f[0].nation_id == t[0].nation_id and f[0].mission == "AIR_SUPERIORITY")
                wt *= max(0.2, 1 - min(0.8, 0.5 * esc / max(1.0, act)) * (1 + air_mod(tn, "escort")))
                wt *= 1 - 0.4 * (t[0].family == "strat_bomber") * min(1.0, air_mod(tn, "stealth") / 0.4)
            weights.append(wt)
        tot = sum(weights) or 1.0
        boost = 1 + (air_mod(n, "intercept") + air_mod(n, "intercept_detect")) * intercept
        for t, wt in zip(foes, weights):
            shots = min(act * wt / tot, 3.0 * t[1])                    # COMBAT_MULTIPLANE_CAP
            k = shots * kill_chance(st, t[2]) * boost
            lose(t, k, "air")
            e[3] += k
            if t[0].family not in ("fighter", "heavy_fighter"):        # the bombers' gunners answer
                back = min(t[1], shots) * 0.3
                lose(e, back * kill_chance(t[2], st), "air")
        AIR["fights"][z] = AIR["round"]


def ground_aa(z, fl, pm):
    """Anti-air guns around the enemy's factories hit the bombers that come for them (divisions' own AA meets the CAS)."""
    zone = AIR_ZONES[z]
    for e in fl:
        w = e[0]
        if w.mission != "STRAT_BOMB":
            continue
        aa = max((STATES[sid].get("aa", 0) for sid in zone["states"] if STATES[sid]["controller"] in NATIONS[w.nation_id]["at_war_with"]),
                 default=0)
        if aa:
            lose(e, e[1] * min(0.02, 0.0012 * aa) * random.uniform(0.6, 1.4), "aa")


def close_air_support(z, fl, units, by_id, support):
    """CAS over the land battles in the zone: damage to the enemy's divisions, +25% attack for ours (HOI4 air support)."""
    battles = [(t, b) for t, b in LAND_BATTLES.items() if AIR_ZONE_GRID[t[1]][t[0]] == z]
    if not battles:
        return
    by_nation = {}
    for e in fl:
        if e[0].mission == "CAS" and e[1] > 0:
            by_nation.setdefault(e[0].nation_id, []).append(e)
    for nid, es in by_nation.items():
        n = NATIONS[nid]
        fr = friends_of(n)
        mine = []
        for tile, b in battles:
            sides = (b["att"], b["def"])
            for si in (0, 1):
                ours = [by_id[i] for i in sides[si] if i in by_id and by_id[i].nation_id in fr]
                foes = [by_id[i] for i in sides[1 - si] if i in by_id and by_id[i].nation_id in n["at_war_with"]]
                if ours and foes:
                    mine.append((b, foes))
        if not mine:
            continue
        planes = sum(e[1] for e in es)
        cap = sum(b["width"] for b, _ in mine) * 2.0 * (1 + air_mod(n, "cas_present"))   # how many planes the battles can take
        use = min(1.0, cap / max(1.0, planes))
        ga = sum(e[1] * e[2]["gnd"] for e in es) * use * (1 + air_mod(n, "cas"))
        support[(z, nid)] = 0.25 * min(1.0, planes * use / max(1.0, 20.0 * len(mine)))   # AIR_SUPPORT_BASE
        foes_all = [d for _, foes in mine for d in foes]
        share = ga / len(foes_all)
        lost = 0.0
        for d in foes_all:
            red = min(0.75, getattr(d, "aa", 0.0) * 0.0125)            # the division's anti-air takes the edge off
            hits = share * 0.2 * (1 - red)
            arm = 0.7 if d.armor > 0 else 1.0
            before = d.hp
            d.org = max(0.0, d.org - hits * ORG_DAMAGE * arm)
            d.hp -= hits * STR_DAMAGE * arm * TEMPLATE_BY_KEY[d.key].get("casualty", 1.0)
            war_casualties(nid, d.nation_id, (before - d.hp) / d.max_hp * TEMPLATE_BY_KEY[d.key]["man_cost"])
            lost += getattr(d, "aa", 0.0) * 0.0004 * planes * use / len(foes_all)
        for e in es:
            lose(e, lost * e[1] / planes, "div_aa")
            e[0].today["dmg"] += share * len(foes_all) * e[1] / planes / 100.0


def strategic_bombing(z, fl, pm):
    """Bombers over enemy land: factories and air bases knocked out (repaired over the days), war score, war support."""
    zone = AIR_ZONES[z]
    for e in fl:
        w, act, st = e[0], e[1], e[2]
        if w.mission != "STRAT_BOMB" or act <= 0:
            continue
        n = NATIONS[w.nation_id]
        targets = [STATES[sid] for sid in zone["states"] if STATES[sid]["controller"] in n["at_war_with"]]
        if not targets:
            continue
        weights = [(s["civ"] + s["mil"] + s["dock"] + s["refinery"]) * (1 - s.get("bomb", 0.0)) + 0.3 * s.get("air_base", 0) + 0.2
                   for s in targets]
        tot = sum(weights)
        bp = act * st["bomb"] * 2.0                                     # AIR_WING_BOMB_DAMAGE_FACTOR
        for s, wt in zip(targets, weights):
            dmg = bp * wt / tot * 0.000025 * (1 - 0.12 * s.get("aa", 0))  # AA_INDUSTRY_AIR_DAMAGE_FACTOR
            size = s["civ"] + s["mil"] + s["dock"] + s["refinery"]
            s["bomb"] = min(0.9, s.get("bomb", 0.0) + dmg / max(1.0, size))
            victim = NATIONS[s["controller"]]
            war_score_add(n["id"], victim["id"], dmg * 0.6)
            victim["war_support"] = max(10, victim["war_support"] - dmg * 0.4)
            w.today["dmg"] += dmg
            AIR["bombed"][s["id"]] = (EVENT_DAY[0], n["id"])
            AIR["seen"][z] = (EVENT_DAY[0], n["id"])
            note_bombing(n, victim, s, dmg)


def sea_detection(z, fl, n):
    """Chance that n's side spots an enemy fleet in sea zone z this round: the planes it has there
    (HOI4 AIR_MISSION_SPOTTING_FACTORS: patrols 1.5, naval strikes and air superiority 0.5) and radar."""
    fr = friends_of(n)
    spot = sum(e[1] * AIR_SPOTTING.get(e[0].mission, 0.0) for e in fl if e[0].nation_id in fr)
    return min(0.85, 0.10 + 0.55 * (1 - math.exp(-spot / 60.0)) + 0.05 * radar_level(z, n))


def naval_strikes(z, fl):
    """Naval bombers (and CAS and tactical bombers) against enemy ships at sea in the zone, or in its ports."""
    zone = AIR_ZONES[z]
    for e in fl:
        w, act, st = e[0], e[1], e[2]
        if act <= 0 or w.mission not in ("NAVAL_STRIKE", "PORT_STRIKE"):
            continue
        n = NATIONS[w.nation_id]
        if w.mission == "NAVAL_STRIKE":
            if not zone["sea"]:
                continue
            fleets = [f for f in FLEETS if f.ships and not f.docked and f.nation_id in n["at_war_with"]
                      and SEA_REGION[f.y][f.x] == zone["sea_index"]]
            if not fleets or random.random() > sea_detection(z, fl, n):   # first they have to find them
                continue
        else:
            fleets = [f for f in FLEETS if f.ships and f.docked and f.nation_id in n["at_war_with"] and f.port in zone["ports"]]
            if not fleets:
                continue
        mult = 1.0
        f = max(fleets, key=lambda f: sum(sh.hp for sh in f.ships))
        hits = act * min(0.6, 0.03 * st["navt"]) * 0.3
        dmg = hits * st["nav"] * mult * (1 + air_mod(n, "nav"))
        ships = [sh for sh in f.ships if sh.hp > 0]
        aa = sum(sh.st[S_AA] for sh in ships) + sum(sh.st[S_AIR] for sh in ships)   # guns, and the carriers' fighters
        if f.docked:
            ps = state_at(PORTS[f.port]["x"], PORTS[f.port]["y"])
            aa += PORTS[f.port]["level"] * 2 + (ps.get("aa", 0) * 6 if ps else 0)
        lose(e, min(act * 0.2, aa * 0.006 * random.uniform(0.5, 1.5)), "ship_aa")
        sunk = []
        for _ in range(3):   # the damage falls on up to three ships, the big ones first
            if not ships or dmg <= 0:
                break
            sh = random.choices(ships, weights=[s.max_hp for s in ships])[0]
            d = dmg / 2 if len(ships) > 1 else dmg
            sh.hp -= d
            dmg -= d
            w.today["dmg"] += d / 100.0
            if sh.hp <= 0:
                ships.remove(sh)
                sunk.append(sh)
        if sunk:
            f.ships = [sh for sh in f.ships if sh.hp > 0]
            AIR["sunk"][n["id"]] = AIR["sunk"].get(n["id"], 0) + len(sunk)
            for sh in sunk:
                war_ship_sunk([n["id"]], f.nation_id, sh.st[S_COST])
                if f.nation_id == 0 or n["id"] == 0:
                    air_news(f"{'OUR ' if f.nation_id == 0 else ''}{sh.name} ({SHIP_TYPES[sh.type]['name']}) SUNK by "
                             f"{plane_name(n, w.family, w.gen)} of {w.name} {'in port at ' + PORTS[f.port]['name'] if f.docked else 'in the ' + zone['name']}!")
            if not f.ships and f in FLEETS:
                FLEETS.remove(f)


def settle_losses(z, fl):
    """Planes shot down leave their wings; experience, aces and the day's tally."""
    rep = AIR["report"].setdefault(z, {})
    here = {e[0].nation_id for e in fl} | {STATES[sid]["controller"] for sid in AIR_ZONES[z]["states"]}
    for e in fl:
        w, act, st, kills, lost = e
        n = NATIONS[w.nation_id]
        down = int(lost) + (1 if random.random() < lost - int(lost) else 0)
        down = min(down, w.planes)
        w.planes -= down
        w.losses += down
        w.today["lost"] += down
        k = int(kills) + (1 if random.random() < kills - int(kills) else 0)
        w.kills += k
        w.today["kills"] += k
        r = rep.setdefault(w.nation_id, [0, 0, 0.0])
        r[0] += k
        r[1] += down
        r[2] += w.today["dmg"]
        big = AIR.setdefault("battle_tally", {})
        big[z] = big.get(z, 0) + down
        if big[z] >= 200 and once(f"air_battle_{z}"):
            sides = sorted({e2[0].nation_id for e2 in fl}, key=lambda i: -sum(e3[1] for e3 in fl if e3[0].nation_id == i))
            names = [short_name(NATIONS[i]) for i in sides[:3]]
            title = "The Battle of Britain" if AIR_ZONES[z]["name"] == "Southern England" else f"The Air Battle over {AIR_ZONES[z]['name']}"
            fire_news("airbattle.news", NATIONS[sides[0]], {"title": title, "country": AIR_ZONES[z]["name"], "attacker": " and ".join(names),
                                                            "actors": sides, "victims": []})
        if down or k:
            foes = n["at_war_with"]
            foe = next((x for x in here if x in foes), None)
            if foe is None:
                foe = next(iter(foes), None)
            wars = war_pairs().get((w.nation_id, foe), ()) if foe is not None else ()
            if wars and down:
                tally = wars[0].setdefault("planes", {})
                tally[w.nation_id] = tally.get(w.nation_id, 0) + down
            if k and foe is not None:
                war_score_add(w.nation_id, foe, k * 0.003 * st["cost"])
        fought = kills > 0 or lost > 0
        w.xp = min(1000.0, w.xp + (1.0 if fought else 0.3) * (1 + air_mod(n, "xp")))
        if n.get("air_xp_day", 0) < 2.0:   # HOI4 FIELD_EXPERIENCE_MAX_PER_DAY
            g = act * 0.0012 * (1 + air_mod(n, "xp"))
            n["air_xp"] = n.get("air_xp", 0.0) + g
            n["air_xp_day"] = n.get("air_xp_day", 0.0) + g
        track = FAMILY_INFO[w.family][3]
        n["mastery"][track] = n["mastery"].get(track, 0.0) + act * 0.0015
        check_milestones(n)
        maybe_ace(w, n, k, down)


def check_milestones(n):
    d = n.get("air_doctrine")
    if not d:
        return
    for track, label in DOCTRINE_TRACKS:
        if track not in n["milestones"] and n["mastery"].get(track, 0) >= MILESTONE_MASTERY:
            n["milestones"].add(track)
            if n["id"] == 0:
                fx = ", ".join(f"{k} +{v * 100:.0f}%" for k, v in AIR_DOCTRINES[d][3][track].items())
                air_news(f"AIR DOCTRINE: our {label.lower()} have learned their trade - {AIR_DOCTRINES[d][0]} milestone ({fx}).")


def maybe_ace(w, n, kills, down):
    if w.ace and down and random.random() < 0.002 + 0.001 * down:    # ACE_DEATH_CHANCE
        if w.nation_id == 0:
            air_news(f"ACE KILLED: {w.ace['name']} of {w.name} has been shot down after {w.ace['kills']} victories.")
        w.ace = None
    if w.ace:
        w.ace["kills"] += kills
        return
    deeds = kills + (w.today["dmg"] if w.family not in ("fighter", "heavy_fighter") else 0)
    if deeds <= 0 or random.random() > (0.0002 + 0.0004 * deeds) * (1 + air_mod(n, "ace")):
        return
    kind = "fighter" if w.family in ("fighter", "heavy_fighter") else "bomber" if w.family == "strat_bomber" else "support"
    tiers = ACE_TYPES[kind]
    tier = random.choices(list(tiers), weights=[tiers[t][0] for t in tiers])[0]
    used = n.setdefault("aces_used", set())
    famous = [a for a in FAMOUS_ACES.get(nation_key(n), []) if a[3] == kind and a[1] not in used]
    if famous:
        first, last, call, _ = famous[0]
        used.add(last)
    else:
        first, last = ACE_NAMES.get(nation_key(n), ("John", "Smith"))
        first, last, call = random.choice(first.split()), random.choice(last.split()), ""
    name = f"{first} '{call}' {last}" if call else f"{first} {last}"
    w.ace = {"name": name, "tier": tier, "kind": kind, "fx": dict(tiers[tier][1]), "kills": kills}
    if w.nation_id == 0:
        fx = ", ".join(f"{ {'atk': 'attack', 'spd': 'speed', 'agi': 'agility', 'navt': 'naval targeting', 'gnd': 'ground attack', 'bomb': 'bombing', 'rng': 'range'}[k]} +{v * 100:.0f}%"
                       for k, v in tiers[tier][1].items())
        air_news(f"A NEW ACE: {name} of {w.name} ({ {'good': 'skilled', 'unique': 'exceptional', 'genius': 'a genius'}[tier]}: {fx})!")


def air_news(text):
    AIR["log"].append((EVENT_DAY[0], text))
    del AIR["log"][:-80]
    alert(text)


def note_bombing(n, victim, s, dmg):
    """The Blitz: the first heavy raids on a great power's capital make the news."""
    cap = victim["cities"][0] if victim["cities"] else None
    if cap and cap in s["tiles"] and victim["major"]:
        tally = AIR.setdefault("raids", {})
        tally[victim["id"]] = tally.get(victim["id"], 0.0) + dmg
        if tally[victim["id"]] >= 1.0 and once(f"blitz_{nation_key(victim)}"):
            fire_news("blitz.news", n, {"country": CITY_NAMES.get(cap, short_name(victim)), "attacker": short_name(n),
                                        "actors": [n["id"]], "victims": [victim["id"]]})


# ---- every day: reinforcements, training, bases, repairs, the air reports ----

def air_daily(day, pm):
    for n in NATIONS:
        n["air_xp_day"] = 0.0
    for w in list(AIR["wings"]):
        n = NATIONS[w.nation_id]
        if not n["is_alive"]:
            AIR["wings"].remove(w)
            continue
        w.ramp = min(1.0, w.ramp + RAMP_PER_DAY[w.family])
        s = STATES[w.base] if w.base is not None else None
        if s is None or not base_friendly(s, n):   # the base has fallen: fly to the nearest one we still hold
            spot = (s["x"], s["y"]) if s else (n["cities"][0] if n["cities"] else (0, 0))
            nb = best_base(n, None, 0, near=spot)
            if nb is None:
                n["stockpile"][w.family] = n["stockpile"].get(w.family, 0) + w.planes
                AIR["wings"].remove(w)
                if w.nation_id == 0:
                    air_news(f"{w.name} has no air base left and is broken up; its planes go to the air stockpile.")
                continue
            if w.nation_id == 0 and s is not None:
                air_news(f"{w.name} pulls out of {s['name']} to {nb['name']}.")
            w.base = nb["id"]
            w.ramp = 0.1
        if w.zone is not None and coverage(w.base, w.zone, wing_range(w)) <= 0:
            w.zone, w.mission = None, "IDLE"
        if w.mission == "TRAINING":   # HOI4: +7 xp a day up to 300, some accidents
            w.xp = min(max(w.xp, 300.0), w.xp + 7.0) if w.xp < 300 else w.xp
            if random.random() < 0.0005 * w.planes * (1.1 - plane_stat(w.family, w.gen, "rel")):
                w.planes -= 1
                w.losses += 1
                c = AIR["cause"].setdefault(w.nation_id, {})
                c["accident"] = c.get("accident", 0.0) + 1
            n["air_xp"] = n.get("air_xp", 0.0) + 0.003 * w.planes * 0.1
        reinforce_wing(w, n)
        w.today = {"kills": 0, "lost": 0, "dmg": 0.0}
    for s in STATES:
        if s.get("bomb"):
            s["bomb"] = max(0.0, s["bomb"] - max(0.01, 0.08 * s["bomb"]))
    report_air_day(day)
    refresh_base_load()


def reinforce_wing(w, n):
    """Fill the wing from the stockpile; newer planes there replace a few old ones every day (the old ones go back to it)."""
    have = n["stockpile"].get(w.family, 0)
    if have <= 0:
        return
    g = n["stock_gen"].get(w.family, w.gen)
    need = w.size - w.planes
    if need > 0:
        k = min(need, have)
        w.gen = (w.gen * w.planes + g * k) / max(1, w.planes + k)
        w.xp = (w.xp * w.planes + 50.0 * k) / max(1, w.planes + k)   # new pilots straight from the schools
        w.planes += k
        have -= k
        n["stockpile"][w.family] = have
    if have > 0 and w.planes > 0 and g > w.gen + 0.15:
        k = min(have, max(1, int(w.planes * 0.05)))
        old = w.gen
        w.gen += (g - old) * k / w.planes
        n["stock_gen"][w.family] = (g * have - g * k + old * k) / have


def report_air_day(day):
    """The player's air war in a line or two: what we shot down and lost, zone by zone."""
    me = NATIONS[0]
    lines = []
    for z, rep in AIR["report"].items():
        ours = [r for nid, r in rep.items() if nid in friends_of(me)]
        if not ours:
            continue
        k, l = sum(r[0] for r in ours), sum(r[1] for r in ours)
        if k + l >= 3:
            share = AIR["sup"].get(z, {}).get(0, (None, 0))[0]
            lines.append(f"{AIR_ZONES[z]['name']}: shot down {k}, lost {l}" + (f" ({share * 100:.0f}% of the sky)" if share is not None else ""))
    AIR["report"] = {}
    if lines:
        AIR["log"].append((day, "AIR WAR: " + "; ".join(lines)))
        del AIR["log"][:-80]
        if len(lines) <= 2:
            alert("AIR WAR - " + "; ".join(lines))


def transfer_air_force(victim, winner):
    """An annexed country's planes - its wings and its stockpile - go to the winner's stockpile (HOI4: the equipment changes hands)."""
    for w in [w for w in AIR["wings"] if w.nation_id == victim["id"]]:
        victim["stockpile"][w.family] = victim["stockpile"].get(w.family, 0) + w.planes
        g = victim.setdefault("stock_gen", {})
        g[w.family] = (g.get(w.family, w.gen) * (victim["stockpile"][w.family] - w.planes) + w.gen * w.planes) / max(1, victim["stockpile"][w.family])
        AIR["wings"].remove(w)
    for f in AIR_FAMILIES:
        k = victim["stockpile"].get(f, 0)
        if k <= 0:
            continue
        have = winner["stockpile"].get(f, 0)
        wg, vg = winner.setdefault("stock_gen", {}), victim.get("stock_gen", {})
        wg[f] = (wg.get(f, vg.get(f, 0)) * have + vg.get(f, wg.get(f, 0)) * k) / (have + k)
        winner["stockpile"][f] = have + k
        victim["stockpile"][f] = 0
    refresh_base_load()


def ground_air_force(n):
    """A country that capitulates loses its air force."""
    AIR["wings"] = [w for w in AIR["wings"] if w.nation_id != n["id"]]


def new_wing(n, family, base=None, size=100):
    """A new wing from the planes in the air stockpile (at least 10). Returns it, or an error text."""
    have = n["stockpile"].get(family, 0)
    if have < 10:
        return f"Only {have} {FAMILY_INFO[family][0].lower()} in the stockpile (a wing needs 10)"
    if base is None:
        base = best_base(n, None, 0, near=n["cities"][0] if n["cities"] else None)
    if base is None:
        return "We have no air base"
    k = min(size, have)
    w = AirWing(n["id"], family, n["stock_gen"].get(family, max(0, best_gen(n, family))), k, base["id"], size=size)
    w.xp = 50.0
    n["stockpile"][family] = have - k
    AIR["wings"].append(w)
    refresh_base_load()
    return w


def set_wing_mission(w, zone, mission):
    """Send wing w to zone on a mission (changing zone costs efficiency for a while, as in HOI4)."""
    if zone != w.zone:
        w.ramp = 0.1 if w.zone is not None else 0.3
    w.zone, w.mission = zone, mission


def default_mission(w, z):
    sea = AIR_ZONES[z]["sea"] if z is not None and z >= 0 else False
    opts = FAMILY_INFO[w.family][2]
    if w.family in ("nav_bomber",) or (sea and "NAVAL_STRIKE" in opts and w.family != "tac_bomber"):
        return "NAVAL_STRIKE" if sea else "PORT_STRIKE"
    if w.family == "strat_bomber":
        return "STRAT_BOMB"
    return opts[0]


def mission_block(w, z, mission):
    """Why wing w can't fly mission over zone z (None = it can)."""
    if z is None or z < 0:
        return "Pick an air zone"
    if mission not in FAMILY_INFO[w.family][2]:
        return f"{FAMILY_INFO[w.family][0]} can't fly {AIR_MISSION_INFO[mission][0]}"
    zone = AIR_ZONES[z]
    if mission in ("NAVAL_STRIKE", "NAVAL_PATROL") and not zone["sea"]:
        return f"{AIR_MISSION_INFO[mission][0]} needs a sea zone"
    if mission in ("STRAT_BOMB", "CAS", "PORT_STRIKE") and zone["sea"]:
        return f"{AIR_MISSION_INFO[mission][0]} needs a land zone"
    if mission != "TRAINING" and coverage(w.base, z, wing_range(w)) <= 0:
        return f"Out of range ({wing_range(w):.0f} km) from {STATES[w.base]['name']}"
    return None


# ---- the AI's air force ----

def ai_air(n, day, pm, wm, units):
    """The AI's air staff: new wings from the stockpile, missions where the war is, bases within reach."""
    wings = [w for w in AIR["wings"] if w.nation_id == n["id"]]
    for fam in AIR_FAMILIES:
        if n["stockpile"].get(fam, 0) >= (60 if n["major"] else 30):
            got = new_wing(n, fam, size=100)
            if isinstance(got, AirWing):
                wings.append(got)
    if not wings:
        return
    at_war = bool(n["at_war_with"])
    front, battle_z, ind_z, sea_z, port_z = {}, {}, {}, {}, {}
    if at_war:
        borders = ai_borders(pm, wm, day)
        for e in n["at_war_with"]:
            for x, y in list(borders.get((n["id"], e), ()))[::2]:
                z = AIR_ZONE_GRID[y][x]
                front[z] = front.get(z, 0) + 1
        for (x, y), b in LAND_BATTLES.items():
            z = AIR_ZONE_GRID[y][x]
            if z in front or pm[y][x] == n["id"] or pm[y][x] in n["at_war_with"]:
                battle_z[z] = battle_z.get(z, 0) + 1
        for s in STATES:
            if s["controller"] in n["at_war_with"] and s.get("zone", -1) >= 0:
                ind_z[s["zone"]] = ind_z.get(s["zone"], 0) + s["civ"] + s["mil"] + s["dock"]
        for f in FLEETS:
            if f.ships and f.nation_id in n["at_war_with"]:
                if f.docked:
                    z = AIR_ZONE_GRID[PORTS[f.port]["y"]][PORTS[f.port]["x"]]
                    port_z[z] = port_z.get(z, 0) + len(f.ships)
                elif not f.docked:
                    z = AIR["land_zones"] + SEA_REGION[f.y][f.x] if SEA_REGION[f.y][f.x] >= 0 else -1
                    if z >= 0:
                        sea_z[z] = sea_z.get(z, 0) + len(f.ships)
        for z, (when, who) in list(AIR["seen"].items()):   # where the enemy has been bombing us lately
            if day - when < 10 and who in n["at_war_with"]:
                front[z] = front.get(z, 0) + 5
        for sid, (when, who) in AIR["bombed"].items():
            if day - when < 10 and STATES[sid]["controller"] == n["id"]:
                z = STATES[sid]["zone"]
                front[z] = front.get(z, 0) + 8
    n["air_front"] = set(front) | set(battle_z)
    home = state_at(*n["cities"][0]).get("zone", -1) if n["cities"] and state_at(*n["cities"][0]) else -1
    plan = {"fighter": [], "heavy_fighter": [], "cas": [], "tac_bomber": [], "nav_bomber": [], "strat_bomber": []}
    for w in wings:
        if w.planes < 0.25 * w.size and w.mission not in ("IDLE", "TRAINING"):
            w.mission = "IDLE"   # worn out: it rests until the stockpile fills it up again
            continue
        if w.mission == "IDLE" and w.planes < 0.5 * w.size:
            continue
        plan[w.family].append(w)
    assigned = {}

    def send(w, choices, mission):
        """The best zone of choices (zone -> weight) we can reach, spread over the wings; rebase if need be."""
        rng = wing_range(w)
        best, bk = None, None
        for z, wt in choices.items():
            if z is None or z < 0 or mission_block_basic(w, z, mission):
                continue
            cov = coverage(w.base, z, rng)
            alt = None
            if cov < 0.6:
                alt = best_base(n, z, rng)
                if alt is not None:
                    cov2 = coverage(alt["id"], z, rng)
                    if cov2 > cov + 0.2:
                        cov = cov2
                    else:
                        alt = None
            if cov <= 0.2:
                continue
            k = wt * cov / (1 + assigned.get((z, mission), 0)) * (1.3 if z == w.zone else 1.0)
            if bk is None or k > bk:
                best, bk = (z, alt), k
        if best is None:
            return False
        z, alt = best
        if alt is not None and alt["id"] != w.base:
            w.base = alt["id"]
            w.ramp = min(w.ramp, 0.3)
        if (w.zone, w.mission) != (z, mission):
            set_wing_mission(w, z, mission)
        assigned[(z, mission)] = assigned.get((z, mission), 0) + 1
        return True

    for w in plan["fighter"] + plan["heavy_fighter"]:
        if at_war and (front or battle_z):
            ch = {z: front.get(z, 0) + 3 * battle_z.get(z, 0) for z in set(front) | set(battle_z)}
            if not send(w, ch, "AIR_SUPERIORITY"):
                send(w, {home: 1}, "INTERCEPT") or set_wing_mission(w, None, "IDLE")
        elif w.xp < 300 and random.random() < 0.3:
            set_wing_mission(w, w.zone, "TRAINING")
        else:
            send(w, {home: 1}, "AIR_SUPERIORITY") or set_wing_mission(w, None, "IDLE")
    for w in plan["cas"]:
        if at_war and battle_z and send(w, battle_z, "CAS"):
            continue
        if at_war and sea_z and send(w, sea_z, "NAVAL_STRIKE"):
            continue
        if w.xp < 300 and w.mission != "TRAINING":
            set_wing_mission(w, w.zone, "TRAINING")
    for w in plan["tac_bomber"]:
        if at_war:
            if battle_z and (w.id % 2 == 0 or not ind_z) and send(w, battle_z, "CAS"):
                continue
            if ind_z and send(w, ind_z, "STRAT_BOMB"):
                continue
            if sea_z and send(w, sea_z, "NAVAL_STRIKE"):
                continue
        if w.mission != "TRAINING" and w.xp < 300:
            set_wing_mission(w, w.zone, "TRAINING")
    patrol = len(plan["nav_bomber"]) >= 2
    for w in plan["nav_bomber"]:
        if at_war and patrol and sea_z and send(w, sea_z, "NAVAL_PATROL"):
            patrol = False
            continue
        if at_war and (sea_z and send(w, sea_z, "NAVAL_STRIKE") or port_z and send(w, port_z, "PORT_STRIKE")):
            continue
        if w.mission != "TRAINING" and w.xp < 300:
            set_wing_mission(w, w.zone, "TRAINING")
    for w in plan["strat_bomber"]:
        if at_war and ind_z and send(w, ind_z, "STRAT_BOMB"):
            continue
        if w.mission != "TRAINING" and w.xp < 300:
            set_wing_mission(w, w.zone, "TRAINING")
    if not n.get("air_doctrine") and n.get("air_xp", 0) >= AIR_DOCTRINE_COST:
        key = nation_key(n)
        pick = ("strategic_destruction" if key in ("British Empire", "United States") else
                "operational_integrity" if key in ("French Republic", "Kingdom of Italy") else "battlefield_support")
        n["air_doctrine"] = pick
        n["air_xp"] -= AIR_DOCTRINE_COST


def ai_build_score(n, kind, s):
    """Where the AI builds: air bases toward the air war, anti-air and radar over the factories the enemy bombs."""
    base = (s["infra"], s["pop"], -used_slots(s))
    if kind == "air_base":
        return (s.get("zone", -1) in n.get("air_front", ()), s.get("air_base", 0) > 0) + base
    if kind in ("aa", "radar"):
        hit = AIR["bombed"].get(s["id"])
        recent = bool(hit) and EVENT_DAY[0] - hit[0] < 60
        capital = kind == "radar" and bool(n["cities"]) and state_at(*n["cities"][0]) is s
        return (recent, capital, s["civ"] + s["mil"] + s["dock"]) + base
    return base


def mission_block_basic(w, z, mission):
    zone = AIR_ZONES[z]
    if mission in ("NAVAL_STRIKE", "NAVAL_PATROL") and not zone["sea"]:
        return True
    if mission in ("STRAT_BOMB", "CAS", "PORT_STRIKE") and zone["sea"]:
        return True
    return False


# ---- the papers ----
ev("airbattle.news", lambda c: c["data"].get("title", "Battle in the Air"),
   "Over [COUNTRY] the skies are full of fighters and bombers: [ATTACKER] have thrown hundreds of planes into the fight, and "
   "the wrecks lie scattered over fields and sea. Whoever holds the sky here holds the ground beneath it.", "war",
   news_opts("The sky is ours to take.", "We will hold the line in the air.", "The war in the air grows."), news=True)
ev("blitz.news", lambda c: f"Bombs on {c['data'].get('country', '')}",
   "Wave after wave of [ATTACKER] bombers has struck [COUNTRY]. Whole streets lie in ruins, factories burn through the night, "
   "and the people shelter in cellars and underground stations. The bombing will go on as long as the war does.", "war",
   news_opts("The enemy's cities are burning.", "We can take it.", "War from the air."), news=True)


# ---- the air map ([F10]): who holds the sky, zone by zone ----

AIR_SUP_RAMP = ((0.15, 160), (0.35, 131), (0.5, 96), (0.65, 61), (0.85, 32), (1.01, 39))   # our share of the sky -> colour
AIR_FREE = 67          # our planes fly here and nobody contests it


AIR_SEA_DIM = {}


def air_pixel(fx, fy, link, pm, coast):
    """xterm colour of a pixel on the air map: its zone's colour (darker over the sea), dim land and sea elsewhere,
    a dark line where one zone meets the next."""
    z = AIR_ZONE_GRID[fy // 2][fx // 2]
    col = MAP_PAINT["air"].get(z)
    land = type(link) is tuple
    if col is None:
        if land:
            owner = pm[link[1]][link[0]]
            col = dim_shade(hd_shades[NATIONS[owner]["color_id"] if owner != -1 else "neutral"][0])
        else:
            col = 18 if coast else 17
    elif not land:
        c2 = AIR_SEA_DIM.get(col)
        if c2 is None:
            c2 = AIR_SEA_DIM[col] = xterm_darker(col, 0.75)
        col = c2
    for nx, ny in ((fx + 1, fy), (fx, fy + 1)):
        if nx < 2 * WORLD_WIDTH and ny < 2 * WORLD_HEIGHT and AIR_ZONE_GRID[ny // 2][nx // 2] != z:
            return 236 if col in (17, 18) else dim_shade(col)
    return col


def air_share(z, pid=0):
    v = AIR["sup"].get(z, {}).get(pid)
    return v[0] if v else None


AIR_RANGE_RAMP = ((0.34, 22), (0.67, 28), (0.99, 34), (1.01, 40))   # share of a zone in the picked wing's range -> green


def air_paint(pid=0, sel=None):
    cols = {}
    if sel is not None:   # HOI4 shows a picked wing's range: the zones it reaches, brighter the more of it
        rng = wing_range(sel)
        for z in AIR_ZONES:
            c = coverage(sel.base, z["id"], rng) if z["tiles"] else 0.0
            if c > 0:
                cols[z["id"]] = next(col for lim, col in AIR_RANGE_RAMP if c < lim)
        return cols
    for z, d in AIR["sup"].items():
        v = d.get(pid)
        if v is not None:
            cols[z] = next(c for lim, c in AIR_SUP_RAMP if v[0] < lim)
    for w in AIR["wings"]:
        if w.nation_id == pid and w.zone is not None and w.mission not in ("IDLE", "TRAINING") and w.zone not in cols:
            cols[w.zone] = AIR_FREE
    return cols


def air_basic_paint(pid=0, sel=None):
    """(char, attr) by zone for terminals without 256 colours."""
    out = {}
    if sel is not None:
        rng = wing_range(sel)
        for z in AIR_ZONES:
            c = coverage(sel.base, z["id"], rng) if z["tiles"] else 0.0
            if c > 0:
                out[z["id"]] = ("█" if c >= 0.99 else "▓" if c >= 0.5 else "▒", curses.color_pair(2) | curses.A_BOLD)
        return out
    for z, d in AIR["sup"].items():
        v = d.get(pid)
        if v is not None:
            out[z] = ("█", curses.color_pair(6 if v[0] >= 0.6 else 1 if v[0] <= 0.4 else 5) | curses.A_BOLD)
    return out


def draw_air_overlays(stdscr, cam_x, cam_y, vw, vh, oy, cursor, frame, pid, sel_wing):
    """Zone names, air bases, and our planes flying their missions (and the enemy's where we meet them)."""
    labels, taken = [], set()   # the zone names (and how much of their sky we hold) go on top; nothing is drawn under them
    for z in AIR_ZONES:
        if not z["label"]:
            continue
        lx, ly = z["label"]
        if not (cam_x <= lx < cam_x + vw and cam_y <= ly < cam_y + vh):
            continue
        name = z["name"].upper() if len(z["name"]) <= 14 else z["name"]
        sx = lx - cam_x - len(name) // 2
        if 0 <= sx and sx + len(name) < vw:
            share = air_share(z["id"], pid)
            ms = sorted({w.mission for w in AIR["wings"] if w.zone == z["id"] and w.nation_id == pid and w.mission not in ("IDLE", "TRAINING")},
                        key=MISSION_ORDER.index)
            tag = " ".join(MISSION_CODE[m] for m in ms)
            labels.append((z, name, sx, share, tag))
            taken.update((cam_x + sx + i, ly) for i in range(len(name)))
            if share is not None:
                taken.update((lx - 2 + i, ly + 1) for i in range(5))
            if tag:
                ty = ly + (2 if share is not None else 1)
                taken.update((lx - len(tag) // 2 + i, ty) for i in range(len(tag)))

    def put(x, y, ch, attr):
        sx, sy = x - cam_x, y - cam_y
        if 0 <= sx < vw and 0 <= sy < vh and (sx, sy) != cursor and (x, y) not in taken:
            safe_draw(stdscr, sy + oy, sx, ch, attr)
            return True
        return False
    me = NATIONS[pid]
    based = {}
    for w in AIR["wings"]:
        if w.base is not None and w.planes > 0:
            based[w.base] = based.get(w.base, 0) + w.planes
    fr = friends_of(me)
    group = {w.base for w in sel_wing} if isinstance(sel_wing, list) else ({sel_wing.base} if sel_wing is not None else set())
    for s in own_bases(me):   # all our air bases (HOI4 shows them on the air map), with the planes on them
        blink = s["id"] in group and frame % 8 < 4
        put(s["x"], s["y"], GLYPH_AIRBASE, curses.color_pair(21) if blink else curses.color_pair(NATIONS[pid].get("city_pair", 7)) | curses.A_BOLD)
        k = based.get(s["id"], 0)
        if k:
            for i, ch in enumerate(str(k)):
                put(s["x"] + 1 + i, s["y"], ch, curses.color_pair(7) | curses.A_BOLD)
    for sid, k in based.items():   # the enemy's, and our friends', where we fight
        s = STATES[sid]
        c = s["controller"]
        if c < 0 or c == pid:
            continue
        ours = c in fr
        if not ours and air_share(s.get("zone", -1), pid) is None:
            continue
        put(s["x"], s["y"], GLYPH_AIRBASE, curses.color_pair(NATIONS[c].get("city_pair", 7)) | (curses.A_BOLD if ours else 0))
    for sid, (day, who) in AIR["bombed"].items():
        if EVENT_DAY[0] - day <= 3 and frame % 6 < 4:
            s = STATES[sid]
            put(s["x"] + 1, s["y"], GLYPH_FIRE, curses.color_pair(1) | curses.A_BOLD)
    flying = {}
    for w in AIR["wings"]:
        if w.zone is None or w.mission in ("IDLE", "TRAINING") or w.planes <= 0:
            continue
        mine = w.nation_id in friends_of(me)
        if not mine and air_share(w.zone, pid) is None:
            continue   # we don't see enemy planes where we don't fight them
        flying.setdefault(w.zone, []).append((w, mine))
    for z, ws in flying.items():
        zone = AIR_ZONES[z]
        if not zone["tiles"]:
            continue
        lx, ly = zone["label"]
        tiles = set(zone["tiles"])
        for i, (w, mine) in enumerate(ws[:4]):
            k = frame // 3 + w.id * 5
            dx, dy = (k % 13) - 6, ((frame // 9 + w.id) % 3) - 1 + (2 if i % 2 else -2)
            spot = (lx + dx, ly + dy)
            if spot not in tiles:
                spot = (lx - dx, ly - dy) if (lx - dx, ly - dy) in tiles else (lx + dx // 2, ly + (2 if i % 2 else -2))
            sel = (w in sel_wing if isinstance(sel_wing, list) else w is sel_wing) and frame % 8 < 4
            attr = curses.color_pair(21) if sel else curses.color_pair(6 if mine else 1) | curses.A_BOLD
            put(spot[0], spot[1], GLYPH_PLANE, attr)
    for z, name, sx, share, tag in labels:
        lx, ly = z["label"]
        if HD["on"]:   # quiet labels: light grey on dark grey, brighter where the air war is
            pair = hd_exact_pair(253 if share is not None else 246, 236 if share is not None else 234)
            attr = curses.color_pair(pair) | (curses.A_BOLD if share is not None else 0) if pair else curses.A_DIM
        else:
            attr = (curses.color_pair(7) | curses.A_DIM) if share is None else curses.color_pair(7) | curses.A_BOLD
        safe_draw(stdscr, ly - cam_y + oy, sx, name, attr)
        if share is not None:
            txt = f"{share * 100:.0f}%"
            safe_draw(stdscr, ly - cam_y + oy + 1, lx - cam_x - len(txt) // 2, txt,
                      curses.color_pair(6 if share >= 0.5 else 1) | curses.A_BOLD)
        if tag:
            ty = ly - cam_y + oy + (2 if share is not None else 1)
            if ty - oy < vh:
                safe_draw(stdscr, ty, lx - cam_x - len(tag) // 2, tag, curses.color_pair(2) | curses.A_BOLD)


def zone_planes(z, pred):
    return sum(w.planes for w in AIR["wings"] if w.zone == z and w.mission not in ("IDLE", "TRAINING") and pred(w))


def draw_air_panel(stdscr, z, sel_wing, pid, y0, x0, width, y_max, base_state=None):
    """The side panel of the air map: the wing(s) we picked and the missions they can fly over the zone under the
    cursor ([1]-[9]); else our air base under the cursor; else the zone."""
    me = NATIONS[pid]
    fr = friends_of(me)
    group = sel_wing if isinstance(sel_wing, list) else ([sel_wing] if sel_wing is not None else [])
    if group:
        lead = group[0]
        lines = [[("--- ", curses.color_pair(3) | curses.A_BOLD),
                  (fit(lead.name if len(group) == 1 else f"{len(group)} wings: {lead.name}...", width - 8), curses.color_pair(3) | curses.A_BOLD),
                  (" ---", curses.color_pair(3) | curses.A_BOLD)],
                 [(f"{sum(w.planes for w in group)} planes", curses.A_BOLD),
                  (f"  {plane_name(me, lead.family, lead.gen)}" if len(group) == 1 else "", curses.color_pair(3)),
                  (f"  from {fit(STATES[lead.base]['name'], width - 24)}", curses.color_pair(6))]]
        if z is None or z < 0:
            lines.append([("Put the cursor on an air zone.", curses.color_pair(6))])
        else:
            zone = AIR_ZONES[z]
            cov = max(coverage(w.base, z, wing_range(w)) for w in group)
            lines.append([("Over ", curses.color_pair(6)), (fit(zone["name"], width - 22), curses.A_BOLD),
                          (f"  {cov * 100:.0f}% in range" if cov > 0 else "  out of range", frac_attr(cov) if cov > 0 else curses.color_pair(1))])
            lines.append([("MISSIONS:", curses.color_pair(3) | curses.A_BOLD)])
            k = 0
            for m, why in mission_choices(group, z):
                if m == "IDLE":
                    key = "[0]"
                else:
                    k += 1
                    key = f"[{k}]"
                lines.append([(f"{key} ", curses.color_pair(2) | curses.A_BOLD if not why else curses.color_pair(6)),
                              (f"{AIR_MISSION_INFO[m][0]:<18}", curses.A_BOLD if not why else curses.color_pair(6)),
                              ("✓" if not why else fit("✗ " + why, width - 23), curses.color_pair(2) if not why else curses.color_pair(1))])
        now = AIR_MISSION_INFO[lead.mission][0] + (f" over {AIR_ZONES[lead.zone]['name']}" if lead.zone is not None and lead.mission not in ("IDLE", "TRAINING") else "")
        lines.append([("Now: ", curses.color_pair(6)), (fit(now, width - 5), curses.A_NORMAL)])
        lines.append([("[1-9] Fly  [ENTER] First  [ESC] Let go", curses.color_pair(2))])
        lines.append([("Green zones: in range (brighter = more).", curses.color_pair(6))])
    elif base_state is not None:
        s = base_state
        cap, load = base_capacity(s), AIR["base_load"].get(s["id"], 0)
        wings = sorted((w for w in AIR["wings"] if w.base == s["id"]), key=lambda w: (AIR_FAMILIES.index(w.family), w.name))
        lines = [[("--- AIR BASE ---", curses.A_BOLD)],
                 [(fit(s["name"], width - 12), curses.color_pair(6) | curses.A_BOLD), (f"  level {s.get('air_base', 0)}", curses.color_pair(3))],
                 [("Planes ", curses.color_pair(6)), (f"{load}/{cap}", frac_attr(1 - min(1.0, load / max(1, cap))) | curses.A_BOLD),
                  (f"  {len(wings)} wing(s)", curses.A_NORMAL), ("  OVER CAPACITY" if load > cap else "", curses.color_pair(1))]]
        for w in wings[:8]:
            lines.append([(f" {fit(w.name, width - 16):<{width - 15}}", curses.A_NORMAL), (f"{w.planes:>4} {MISSION_CODE[w.mission]}", curses.color_pair(2))])
        if len(wings) > 8:
            lines.append([(f" ...and {len(wings) - 8} more", curses.color_pair(6))])
        stock = [(f, me["stockpile"].get(f, 0)) for f in AIR_FAMILIES if me["stockpile"].get(f, 0)]
        lines.append([("Air stockpile: ", curses.color_pair(6)), (fit("  ".join(f"{FAMILY_INFO[f][1]} {k}" for f, k in stock) or "empty", width - 15), curses.A_NORMAL)])
        lines.append([("[ENTER] Open the air base", curses.color_pair(2) | curses.A_BOLD)])
    else:
        lines = [[("--- AIR ZONE ---", curses.A_BOLD)]]
        if z is None or z < 0:
            lines.append([("No air zone here.", curses.color_pair(6))])
        else:
            zone = AIR_ZONES[z]
            lines.append([(fit(zone["name"], width - 12), curses.color_pair(6) | curses.A_BOLD), ("  sea zone" if zone["sea"] else "  land", curses.color_pair(6))])
            share = air_share(z, pid)
            if share is None:
                lines.append([("No air war over this zone.", curses.color_pair(6))])
            else:
                lines.append([("Sky ", curses.color_pair(6)), (bar(share, 10), frac_attr(share)), (f" {share * 100:.0f}% ours", curses.A_BOLD)])
                pen = AIR["pen"].get(z, {})
                fx = []
                worst = max((pen.get(e, 0) for e in me["at_war_with"]), default=0)
                if worst >= 0.01:
                    fx.append(f"enemy divisions -{worst * 100:.0f}% def")
                if pen.get(pid, 0) >= 0.01:
                    fx.append(f"ours -{pen[pid] * 100:.0f}% def")
                if fx:
                    lines.append([(fit(", ".join(fx), width), curses.color_pair(3))])
            ours = [w for w in AIR["wings"] if w.zone == z and w.nation_id in fr and w.mission not in ("IDLE", "TRAINING")]
            if ours:
                by = {}
                for w in ours:
                    by[w.mission] = by.get(w.mission, 0) + w.planes
                lines.append([("Ours: ", curses.color_pair(6)), (fit("  ".join(f"{AIR_MISSION_INFO[m][1]} {k}" for m, k in by.items()), width - 6), curses.color_pair(2) | curses.A_BOLD)])
            if share is not None:
                seen = zone_planes(z, lambda w: w.nation_id in me["at_war_with"])
                lines.append([("Enemy planes seen: ", curses.color_pair(6)), (f"~{seen}", curses.color_pair(1) | curses.A_BOLD)])
            rep = AIR["report"].get(z, {})
            k = sum(r[0] for nid, r in rep.items() if nid in fr)
            l = sum(r[1] for nid, r in rep.items() if nid in fr)
            if k or l:
                lines.append([("Today: ", curses.color_pair(6)), (f"shot down {k}", curses.color_pair(2)), (f", lost {l}", curses.color_pair(1))])
            bases = [STATES[sid] for sid in zone["states"] if STATES[sid].get("air_base")]
            if bases:
                mine = [s for s in bases if s["controller"] in fr]
                lines.append([("Air bases: ", curses.color_pair(6)), (f"{len(mine)} ours ({sum(base_capacity(s) for s in mine)} planes)", curses.A_NORMAL),
                              (f", {len(bases) - len(mine)} theirs" if len(bases) > len(mine) else "", curses.color_pair(1))])
            aa = [STATES[sid] for sid in zone["states"] if STATES[sid].get("aa")]
            if aa:
                lines.append([("Anti-air: ", curses.color_pair(6)), (fit(", ".join(f"{s['name']} {s['aa']}" for s in aa[:3]), width - 10), curses.A_NORMAL)])
            rl = radar_level(z, me)
            el = max((radar_level(z, NATIONS[e]) for e in me["at_war_with"]), default=0) if share is not None else 0
            if rl or el:
                lines.append([("Radar: ", curses.color_pair(6)), (f"ours level {rl}" if rl else "none of ours", curses.color_pair(2) if rl else curses.A_NORMAL),
                              (f", theirs level {el}" if el else "", curses.color_pair(1))])
            bombed = [STATES[sid] for sid in zone["states"] if STATES[sid].get("bomb", 0) >= 0.05]
            if bombed:
                lines.append([("Bomb damage: ", curses.color_pair(6)),
                              (fit(", ".join(f"{s['name']} {s['bomb'] * 100:.0f}%" for s in bombed[:3]), width - 13), curses.color_pair(1))])
        if z is not None and z >= 0:
            lines.append([("[ENTER] Our wings that can reach it", curses.color_pair(2) | curses.A_BOLD)])
            lines.append([(f"Air bases: [ENTER] on one ({GLYPH_AIRBASE})", curses.color_pair(6))])
    for i, parts in enumerate(lines):
        if y0 + i > y_max:
            break
        draw_parts(stdscr, y0 + i, x0, parts, x0 + width)


def air_battle_note(tile, pid=0):
    """What the air war does to the land battle on this tile, for the sidebar."""
    z = AIR_ZONE_GRID[tile[1]][tile[0]] if AIR_ZONE_GRID else -1
    if z < 0:
        return None
    share = air_share(z, pid)
    sup = AIR["support"].get((z, pid), 0.0)
    if share is None and not sup:
        return None
    me = NATIONS[pid]
    pen_enemy = max((AIR["pen"].get(z, {}).get(e, 0.0) for e in me["at_war_with"]), default=0.0)
    pen_us = AIR["pen"].get(z, {}).get(pid, 0.0)
    pen_enemy, pen_us = (pen_enemy if pen_enemy >= 0.01 else 0.0), (pen_us if pen_us >= 0.01 else 0.0)
    out = f"Air: {share * 100:.0f}% ours" if share is not None else "Air:"
    if pen_enemy:
        out += f", enemy -{pen_enemy * 100:.0f}% def"
    if pen_us:
        out += f", us -{pen_us * 100:.0f}% def"
    if sup:
        out += f", CAS +{sup * 100:.0f}% atk"
    return out


# ---- the AIR FORCE tab of the Military screen ----

def air_rows(player):
    bases = sorted(own_bases(player), key=lambda s: (-base_planes(s["id"]), -s.get("air_base", 0), s["name"]))
    rows = [("base", s) for s in bases]
    rows += [("wing", w) for w in sorted((w for w in AIR["wings"] if w.nation_id == player["id"]),
                                         key=lambda w: (AIR_FAMILIES.index(w.family), w.name))]
    rows += [("new", f) for f in AIR_FAMILIES if player["stockpile"].get(f, 0) >= 10]
    rows += [("doctrine", k) for k in AIR_DOCTRINES]
    return rows


def draw_air_tab(stdscr, player, rows, sel, top, H, W, width):
    x_max = W - 2
    wings = [w for w in AIR["wings"] if w.nation_id == player["id"]]
    depot = [(f, player["stockpile"].get(f, 0)) for f in AIR_FAMILIES if player["stockpile"].get(f, 0) or best_gen(player, f) >= 0]
    rate = air_output(player)
    draw_parts(stdscr, top, 2, [("AIR FORCE ", curses.color_pair(3) | curses.A_BOLD), (f"{len(wings)} wings, {sum(w.planes for w in wings)} planes", curses.A_BOLD),
                                ("   AIR STOCKPILE: ", curses.color_pair(3) | curses.A_BOLD),
                                ("  ".join(f"{FAMILY_INFO[f][1]} {k}" + (f" +{rate[f]:.1f}/d" if rate.get(f) else "") for f, k in depot) or "none", curses.A_NORMAL),
                                ("   air XP ", curses.color_pair(6)), (f"{player.get('air_xp', 0):.0f}", curses.A_BOLD),
                                ("   doctrine ", curses.color_pair(6)),
                                (AIR_DOCTRINES[player["air_doctrine"]][0] if player.get("air_doctrine") else "none", curses.color_pair(2) | curses.A_BOLD),
                                ("   air staff ", curses.color_pair(6)),
                                ("AUTO" if player.get("air_auto") else "manual", curses.color_pair(2 if player.get("air_auto") else 3) | curses.A_BOLD)], x_max)
    safe_draw(stdscr, top + 1, 2, fit(f"   {'Wing':<27}{'Plane':<15}{'Planes':<15}{'Base':<18}{'Zone':<22}{'Mission':<12}{'Eff':<9}{'Pilots':<10}Kills/Lost  Ace",
                                      width), curses.color_pair(6))
    room = H - 6 - (top + 2) - 6
    start = scroll_window(rows, sel, room)
    for line, (kind, data) in enumerate(rows[start:start + room]):
        i = start + line
        y = top + 2 + line
        is_sel = i == sel
        mark = "►" if is_sel else " "
        if kind == "base":
            s_ = data
            cap, load = base_capacity(s_), AIR["base_load"].get(s_["id"], 0)
            nw = sum(1 for w in AIR["wings"] if w.base == s_["id"])
            parts = [(f" {mark} {GLYPH_AIRBASE} AIR BASE {fit(s_['name'], 20):<21}", curses.color_pair(3) | curses.A_BOLD),
                     (f"level {s_.get('air_base', 0):<3}", curses.A_NORMAL), (bar(min(1.0, load / max(1, cap)), 6), frac_attr(1 - min(1.0, load / max(1, cap)))),
                     (f" {load:>4}/{cap:<5} planes  ", curses.A_NORMAL), (f"{nw} wing(s)", curses.color_pair(6)),
                     ("  OVER CAPACITY" if load > cap else "", curses.color_pair(1) | curses.A_BOLD)]
        elif kind == "wing":
            w = data
            eff = wing_eff(w) if w.zone is not None else 0.0
            fill = w.planes / max(1, w.size)
            parts = [(f" {mark} {fit(w.name, 25):<26}", curses.A_BOLD), (f"{fit(plane_name(player, w.family, w.gen), 14):<15}", curses.color_pair(3)),
                     (bar(fill, 6), frac_attr(fill)), (f" {w.planes:>3}/{w.size:<3} ", curses.A_NORMAL),
                     (f"{fit(STATES[w.base]['name'] if w.base is not None else '-', 17):<18}", curses.color_pair(6)),
                     (f"{fit(AIR_ZONES[w.zone]['name'] if w.zone is not None else '-', 21):<22}", curses.A_NORMAL),
                     (f"{AIR_MISSION_INFO[w.mission][1]:<12}", curses.color_pair(2) if w.mission not in ("IDLE",) else curses.color_pair(6)),
                     (bar(eff, 4), frac_attr(eff)), (f" {eff * 100:3.0f}% ", curses.A_NORMAL),
                     (f"{air_xp_level(w.xp)[1]:<10}", curses.color_pair(3)), (f"{w.kills:>5}/{w.losses:<5} ", curses.A_NORMAL),
                     (fit(w.ace["name"], 22) if w.ace else "", curses.color_pair(3) | curses.A_BOLD)]
        elif kind == "new":
            f = data
            parts = [(f" {mark} + Deploy a wing of {FAMILY_INFO[f][0]}", curses.color_pair(2) | curses.A_BOLD),
                     (f"  ({plane_name(player, f, player['stock_gen'].get(f, 0))}, {player['stockpile'].get(f, 0)} in the air stockpile)", curses.color_pair(6))]
        else:
            name, desc, base, ms = AIR_DOCTRINES[data]
            have = player.get("air_doctrine") == data
            parts = [(f" {mark} Doctrine: {name:<24}", curses.A_BOLD | (curses.color_pair(2) if have else 0)),
                     (fit(desc, 70) + "   ", curses.color_pair(6)),
                     ("ADOPTED" if have else (f"{AIR_DOCTRINE_COST} air XP" if not player.get("air_doctrine") else "-"),
                      curses.color_pair(2) | curses.A_BOLD if have else curses.color_pair(3))]
        sel_line(stdscr, y, width, is_sel, parts, x_max)
    draw_rule(stdscr, H - 8, 0, W - 1)
    if not rows:
        return
    kind, data = rows[sel]
    if kind == "base":
        s_ = data
        reach = base_reach(s_, fighter_range(player))
        draw_parts(stdscr, H - 7, 2, [(f"{s_['name']}: ", curses.A_BOLD), (f"our fighters ({fighter_range(player):.0f} km) reach ", curses.color_pair(6)),
                                      (fit(", ".join(f"{AIR_ZONES[z]['name']} {c * 100:.0f}%" for c, z in reach[:6]) or "nothing", width - 40), curses.A_NORMAL)], x_max)
        safe_draw(stdscr, H - 4, 2, fit("[ENTER] Open the air base: its wings, new wings from the air stockpile, a bigger base", width), curses.color_pair(2))
    elif kind == "wing":
        w = data
        st = wing_stats(w)
        draw_parts(stdscr, H - 7, 2, [(f"{w.name}: ", curses.A_BOLD), (f"{plane_name(player, w.family, w.gen)} ({FAMILY_INFO[w.family][0]})   ", curses.color_pair(3)),
                                      (f"range {st['rng']:.0f} km  speed {st['spd']:.0f}  agility {st['agi']:.0f}  attack {st['atk']:.0f}  "
                                       f"defence {st['dfn']:.0f}" + (f"  ground {st['gnd']:.0f}" if st["gnd"] else "") +
                                       (f"  bombing {st['bomb']:.0f}" if st["bomb"] else "") + (f"  naval {st['nav']:.0f}" if st["nav"] >= 5 else ""),
                                       curses.A_NORMAL)], x_max)
        z = w.zone
        cov = coverage(w.base, z, wing_range(w)) if z is not None else 0.0
        draw_parts(stdscr, H - 6, 2, [(AIR_MISSION_INFO[w.mission][0] + ": ", curses.color_pair(2) | curses.A_BOLD), (AIR_MISSION_INFO[w.mission][2], curses.color_pair(6)),
                                      (f"   zone {cov * 100:.0f}% in range" if z is not None else "", curses.A_NORMAL),
                                      (f"   getting used to the zone: {w.ramp * 100:.0f}%" if w.ramp < 1 else "", curses.color_pair(3))], x_max)
        parts = [("Ace: ", curses.color_pair(3) | curses.A_BOLD), (f"{w.ace['name']} ({w.ace['tier']}), {w.ace['kills']} victories   ", curses.A_NORMAL)] if w.ace else []
        cause = AIR["cause"].get(player["id"], {})
        lost = [(cause.get(k, 0.0), lbl) for k, lbl in (("air", "to enemy planes"), ("aa", "to anti-air guns"), ("div_aa", "to the divisions' AA"),
                                                         ("ship_aa", "to the ships' AA"), ("accident", "in accidents"))]
        if any(v >= 0.5 for v, _ in lost):
            parts += [("Planes lost so far: ", curses.color_pair(6)), (", ".join(f"{v:.0f} {lbl}" for v, lbl in lost if v >= 0.5), curses.A_NORMAL)]
        if parts:
            draw_parts(stdscr, H - 5, 2, parts, x_max)
        safe_draw(stdscr, H - 4, 2, fit("[ENTER] Send it: pick an air zone on the air map   [M] Mission   [B] Base   [+/-] Wing size   [DEL] Disband", width),
                  curses.color_pair(2))
    elif kind == "new":
        f = data
        st = plane_stats(f, player["stock_gen"].get(f, 0))
        draw_parts(stdscr, H - 7, 2, [(f"{FAMILY_INFO[f][0]}: ", curses.A_BOLD), (f"range {st['rng']:.0f} km, speed {st['spd']:.0f} km/h, "
                                                                                    f"{', '.join(AIR_MISSION_INFO[m][0] for m in FAMILY_INFO[f][2])}", curses.color_pair(6))], x_max)
        safe_draw(stdscr, H - 4, 2, "[ENTER] Deploy a wing of up to 100 planes at our best air base (or open an air base to choose where)", curses.color_pair(2))
    else:
        name, desc, base, ms = AIR_DOCTRINES[data]
        fx = lambda d: ", ".join(f"{k.replace('_', ' ')} +{v * 100:.0f}%" for k, v in d.items())
        draw_parts(stdscr, H - 7, 2, [(name + ": ", curses.A_BOLD), (fx(base), curses.color_pair(2))], x_max)
        parts = [("Milestones: ", curses.color_pair(6))]
        for track, label in DOCTRINE_TRACKS:
            done = player.get("air_doctrine") == data and track in player.get("milestones", ())
            m = player.get("mastery", {}).get(track, 0.0)
            parts.append((f"{label} ({fx(ms[track])}) {'✓' if done else f'{min(m, MILESTONE_MASTERY):.0f}/{MILESTONE_MASTERY}'}   ",
                          curses.color_pair(2) if done else curses.A_NORMAL))
        draw_parts(stdscr, H - 6, 2, parts, x_max)
        safe_draw(stdscr, H - 4, 2, fit("[ENTER] Adopt this doctrine. Milestones come as each kind of plane gains experience in battle.", width),
                  curses.color_pair(2))


WING_SIZES = (10, 20, 50, 100, 150, 200)


def do_air_tab(rows, sel, key, player, state):
    """Keys on the AIR FORCE tab. Returns a message or None; state['goto_wing'] asks for the air map."""
    enter = key in (10, 13, curses.KEY_ENTER)
    kind, data = rows[sel] if rows else (None, None)
    if kind == "base" and enter:
        state["goto_base"] = data["id"]
        return None
    if key in (ord('a'), ord('A')):
        player["air_auto"] = not player.get("air_auto")
        if player["air_auto"]:
            return ("AIR STAFF: our air staff now runs the air force - new wings, bases and missions where the war is "
                    "(wings you send by hand may be re-tasked). [A] again to take over.")
        return "AIR STAFF: you command the air force again; the wings keep their last orders."
    if kind == "wing":
        w = data
        if enter:
            state["goto_wing"] = w
            return f"{w.name}: put the cursor on an air zone and press [ENTER]."
        if key in (ord('m'), ord('M')):
            return cycle_wing_mission(w)
        if key in (ord('b'), ord('B')):
            bases = sorted(own_bases(player), key=lambda s: (-(coverage(s["id"], w.zone, wing_range(w)) if w.zone is not None else 0),
                                                             tile_km((s["x"], s["y"]), (STATES[w.base]["x"], STATES[w.base]["y"]))))
            if not bases:
                return "We have no air bases."
            i = next((k for k, s in enumerate(bases) if s["id"] == w.base), -1)
            nb = bases[(i + 1) % len(bases)]
            w.base = nb["id"]
            w.ramp = min(w.ramp, 0.3)
            refresh_base_load()
            cap = base_capacity(nb)
            return f"{w.name} moves to {nb['name']} (air base {nb['air_base']}, {AIR['base_load'].get(nb['id'], 0)}/{cap} planes)."
        if key in (ord('+'), ord('='), ord('-'), ord('_')):
            i = min(range(len(WING_SIZES)), key=lambda k: abs(WING_SIZES[k] - w.size))
            i = max(0, min(len(WING_SIZES) - 1, i + (1 if key in (ord('+'), ord('=')) else -1)))
            w.size = WING_SIZES[i]
            if w.planes > w.size:
                player["stockpile"][w.family] = player["stockpile"].get(w.family, 0) + w.planes - w.size
                w.planes = w.size
            return f"{w.name}: wing size {w.size} planes."
        if key in (curses.KEY_DC, curses.KEY_BACKSPACE, 127, 8):
            player["stockpile"][w.family] = player["stockpile"].get(w.family, 0) + w.planes
            AIR["wings"].remove(w)
            refresh_base_load()
            return f"{w.name} is disbanded; its {w.planes} planes go back to the air stockpile."
        return None
    if kind == "new" and enter:
        got = new_wing(player, data)
        if isinstance(got, str):
            return f"LOCKED: {got}."
        state["sel_wing"] = got
        return f"SUCCESS: {got.name} is formed at {STATES[got.base]['name']} with {got.planes} {plane_name(player, got.family, got.gen)} - [ENTER] on it to send it."
    if kind == "doctrine" and enter:
        if player.get("air_doctrine"):
            return "We already follow an air doctrine."
        if player.get("air_xp", 0) < AIR_DOCTRINE_COST:
            return f"LOCKED: Needs {AIR_DOCTRINE_COST} air experience (we have {player.get('air_xp', 0):.0f}) - it comes from flying and fighting."
        player["air_xp"] -= AIR_DOCTRINE_COST
        player["air_doctrine"] = data
        check_milestones(player)
        return f"SUCCESS: our air force adopts {AIR_DOCTRINES[data][0]}."
    return None


def cycle_wing_mission(w):
    opts = list(FAMILY_INFO[w.family][2]) + ["IDLE"]
    i = opts.index(w.mission) if w.mission in opts else -1
    for k in range(1, len(opts) + 1):
        m = opts[(i + k) % len(opts)]
        if m in ("IDLE", "TRAINING") or (w.zone is not None and mission_block(w, w.zone, m) is None):
            set_wing_mission(w, w.zone if m != "IDLE" else w.zone, m)
            return f"{w.name}: {AIR_MISSION_INFO[m][0]} - {AIR_MISSION_INFO[m][2]}."
    return f"{w.name}: send it to a zone first ([ENTER])."


def assign_wing_here(w, z):
    """[ENTER] on the air map with a wing picked: fly its mission (or the usual one for the zone) over zone z."""
    if z is None or z < 0:
        return "That isn't an air zone."
    mission = w.mission if w.mission not in ("IDLE", "TRAINING") and mission_block(w, z, w.mission) is None else default_mission(w, z)
    why = mission_block(w, z, mission)
    if why:
        alt = best_base(NATIONS[w.nation_id], z, wing_range(w))
        if alt is not None and "range" in why:
            w.base = alt["id"]
            refresh_base_load()
            why = mission_block(w, z, mission)
            if why is None:
                set_wing_mission(w, z, mission)
                return f"{w.name} moves to {alt['name']} and flies {AIR_MISSION_INFO[mission][0]} over {AIR_ZONES[z]['name']}."
        return f"LOCKED: {why}."
    set_wing_mission(w, z, mission)
    return (f"{w.name}: {AIR_MISSION_INFO[mission][0]} over {AIR_ZONES[z]['name']} ({coverage(w.base, z, wing_range(w)) * 100:.0f}% in range) - "
            f"{AIR_MISSION_INFO[mission][2]}.")


# ======================= PUPPETS: AUTONOMY AND SUBJECT COLOURS (HOI4) =======================
# Every puppet has a freedom score (0-100%) on HOI4's ladder of autonomy levels: Integrated Puppet, Puppet,
# Colony, Dominion - or, under a fascist overlord, Reichskommissariat, Reichsprotektorat, Satellite. The level
# decides what the overlord gets (part of the puppet's factories and resources, part of the war score it wins),
# whether it may refuse a call to war, and how fast its freedom grows. Freedom rises with the resources the
# puppet sends its overlord and the war score it wins (HOI4: 0.005 a day per resource sent, 0.6 x war score),
# by half if the overlord capitulates, and moves with military attaches (-/+5%) and lend-lease. Either side
# can pay 50 PP to change the level once the score is within 10% of its edge; at the bottom the overlord can
# annex (300 PP), at the top the puppet can break free (300 PP). On the map puppets wear their overlord's colour.

AUTONOMY_LEVELS = {   # HOI4 common/autonomous_states: min_freedom_level, cic/mic_to_overlord_factor, extra_trade_to_overlord_factor,
                      # peace_score_ratio_transferred_to_overlord, can_decline_call_to_war, autonomy_gain_global_factor,
                      # conscription_factor, ai_subject_wants_higher, ai_overlord_wants_lower
    "integrated_puppet":  {"name": "Integrated Puppet", "min": 0.2, "civ": 0.25, "mil": 0.75, "trade": 1.0, "peace": 0.2,
                           "decline": False, "gain": 1.0, "conscription": 0.0, "up": 1.0, "down": 0.0},
    "puppet":             {"name": "Puppet", "min": 0.4, "civ": 0.0, "mil": 0.0, "trade": 1.0, "peace": 0.1,
                           "decline": False, "gain": 1.0, "conscription": 0.0, "up": 1.0, "down": 1.0},
    "colony":             {"name": "Colony", "min": 0.6, "civ": 0.0, "mil": 0.0, "trade": 0.5, "peace": 0.1,
                           "decline": False, "gain": 1.0, "conscription": 0.0, "up": 1.0, "down": 1.0},
    "dominion":           {"name": "Dominion", "min": 0.8, "civ": 0.0, "mil": 0.0, "trade": 0.25, "peace": 0.05,
                           "decline": True, "gain": 1.0, "conscription": 0.0, "up": 0.0, "down": 1.0},
    "reichskommissariat": {"name": "Reichskommissariat", "min": 0.2, "civ": 0.25, "mil": 0.65, "trade": 1.0, "peace": 0.1,
                           "decline": False, "gain": 0.7, "conscription": -0.5, "up": 1.0, "down": 0.0},
    "reichsprotektorat":  {"name": "Reichsprotektorat", "min": 0.5, "civ": 0.25, "mil": 0.0, "trade": 0.6, "peace": 0.05,
                           "decline": False, "gain": 0.7, "conscription": -0.25, "up": 1.0, "down": 1.0},
    "satellite":          {"name": "Satellite", "min": 0.8, "civ": 0.0, "mil": 0.0, "trade": 0.4, "peace": 0.1,
                           "decline": False, "gain": 0.7, "conscription": 0.0, "up": 1.0, "down": 1.0},
}
AUTONOMY_LADDER = {"fascist": ("reichskommissariat", "reichsprotektorat", "satellite"),
                   "other": ("integrated_puppet", "puppet", "colony", "dominion")}
AUTONOMY_DEFAULT = {"fascist": "reichsprotektorat", "other": "puppet"}   # HOI4: default = yes
AUTONOMY_CHANGE_PP, AUTONOMY_ANNEX_PP, AUTONOMY_FREE_PP = 50, 300, 300   # HOI4 AUTONOMY_LEVEL_CHANGE_PP_COST_BASE / _ANNEX / _FREE
AUTONOMY_REACH = 0.10          # MAX_SCORE_DIFF_TO_CHANGE_AUTONOMY: how near the edge a level change can be made
AUTONOMY_SANCTUARY = 30        # AUTONOMY_LEVEL_CHANGE_SANCTUARY: days after a change before the next one
RESOURCE_AUTONOMY = 0.005      # a day per resource sent to the overlord (RESOURCE_SENT_AUTONOMY_DAILY_FACTOR), of a bar of
                               # max(100, 10 x the puppet's factories) points: big puppets need more to move
WAR_SCORE_AUTONOMY = 0.6 * 0.03   # % per point of war score the puppet wins (WAR_SCORE_AUTONOMY_FACTOR, our war score's scale)
CAPITULATE_AUTONOMY = 0.5      # AUTONOMY_FREEDOM_FROM_CAPITULATE
ATTACHE_EFFECT, ATTACHE_PP, ATTACHE_DAYS = 0.05, 25, 60   # ATTACHE_TO_SUBJECT/OVERLORD_EFFECT; cost; how long they stay
LEND_AUTONOMY = {"to_overlord": 0.05, "to_puppet": -0.01}  # LL_TO_OVERLORD / LL_TO_PUPPET_AUTONOMY_DAILY_FACTOR (per 100 IC lent)
AUTONOMY_SEEN = {}             # (war id, puppet id) -> its war score when last counted
PUPPET_COLOURS = {"ver": 0, "applied": -1, "orig": {}, "basic": {}}
PUPPET_LEADERS = {   # who governs a puppet that takes its overlord's ideology (the real collaborators and party leaders)
    ("German Reich", "Norway"): "Vidkun Quisling", ("German Reich", "French Republic"): "Philippe Pétain",
    ("German Reich", "Netherlands"): "Anton Mussert", ("German Reich", "Belgium"): "Léon Degrelle",
    ("German Reich", "Denmark"): "Frits Clausen", ("German Reich", "Czechoslovakia"): "Emil Hácha",
    ("German Reich", "Second Polish Republic"): "Hans Frank", ("German Reich", "Yugoslavia"): "Milan Nedić",
    ("German Reich", "Greece"): "Georgios Tsolakoglou", ("German Reich", "Hungary"): "Ferenc Szálasi",
    ("German Reich", "Romania"): "Horia Sima", ("German Reich", "Soviet Union"): "Andrey Vlasov",
    ("German Reich", "British Empire"): "Oswald Mosley", ("German Reich", "Kingdom of Italy"): "Benito Mussolini",
    ("German Reich", "Lithuania"): "Hinrich Lohse", ("German Reich", "Latvia"): "Hinrich Lohse",
    ("German Reich", "Estonia"): "Hjalmar Mäe", ("German Reich", "Luxembourg"): "Gustav Simon",
    ("German Reich", "Switzerland"): "Rolf Henne", ("German Reich", "Sweden"): "Sven Olov Lindholm",
    ("German Reich", "Austria"): "Arthur Seyss-Inquart", ("German Reich", "Bulgaria"): "Aleksandar Tsankov",
    ("Soviet Union", "Second Polish Republic"): "Bolesław Bierut", ("Soviet Union", "Czechoslovakia"): "Klement Gottwald",
    ("Soviet Union", "Hungary"): "Mátyás Rákosi", ("Soviet Union", "Romania"): "Gheorghe Gheorghiu-Dej",
    ("Soviet Union", "Bulgaria"): "Georgi Dimitrov", ("Soviet Union", "German Reich"): "Walter Ulbricht",
    ("Soviet Union", "Finland"): "Otto Wille Kuusinen", ("Soviet Union", "Estonia"): "Johannes Vares",
    ("Soviet Union", "Latvia"): "Augusts Kirhenšteins", ("Soviet Union", "Lithuania"): "Justas Paleckis",
    ("Soviet Union", "Yugoslavia"): "Josip Broz Tito", ("Soviet Union", "Greece"): "Nikos Zachariadis",
    ("Soviet Union", "Austria"): "Johann Koplenig", ("Soviet Union", "French Republic"): "Maurice Thorez",
    ("Soviet Union", "Kingdom of Italy"): "Palmiro Togliatti", ("Soviet Union", "Spain"): "Dolores Ibárruri",
    ("Soviet Union", "Turkey"): "Şefik Hüsnü", ("Soviet Union", "Norway"): "Peder Furubotn",
    ("British Empire", "German Reich"): "Konrad Adenauer", ("British Empire", "Kingdom of Italy"): "Alcide De Gasperi",
    ("French Republic", "German Reich"): "Konrad Adenauer", ("United States", "German Reich"): "Konrad Adenauer",
}


def reset_autonomy():
    AUTONOMY_SEEN.clear()
    PUPPET_COLOURS.update({"ver": PUPPET_COLOURS["ver"] + 1, "applied": -1})


def ladder_of(p):
    o = NATIONS[p["overlord"]]
    return AUTONOMY_LADDER["fascist" if o["ideology"] == "Fascist" else "other"]


def level_for_score(ladder, score):
    lvl = ladder[0]
    for k in ladder:
        if score >= AUTONOMY_LEVELS[k]["min"]:
            lvl = k
    return lvl


def autonomy(p):
    """p's autonomy ({"score", "level", "changed", ...}); None if p isn't a subject."""
    if p.get("overlord") is None:
        return None
    a = p.get("autonomy")
    lad = ladder_of(p)
    if a is None:
        lvl = AUTONOMY_DEFAULT["fascist" if lad is AUTONOMY_LADDER["fascist"] else "other"]
        a = p["autonomy"] = {"score": AUTONOMY_LEVELS[lvl]["min"] + 0.05, "level": lvl, "changed": EVENT_DAY[0],
                             "trend": 0.0, "gains": {}, "attache": {}}
    elif a["level"] not in lad:   # the overlord's ideology changed sides: the nearest level on its ladder
        a["level"] = level_for_score(lad, a["score"])
    return a


def autonomy_level(p):
    a = autonomy(p)
    return AUTONOMY_LEVELS[a["level"]] if a else None


def autonomy_new(p):
    """A new puppet starts on its overlord's default level (HOI4), just inside it."""
    p.pop("autonomy", None)
    autonomy(p)
    PUPPET_COLOURS["ver"] += 1


def autonomy_moves(p):
    """{"up", "down", "annex", "free"}: None where that change can be made now, else why not."""
    a = autonomy(p)
    lad = ladder_of(p)
    i = lad.index(a["level"])
    lv = AUTONOMY_LEVELS[a["level"]]
    sc = a["score"]
    wait = AUTONOMY_SANCTUARY - (EVENT_DAY[0] - a["changed"])
    hold = f"The level changed {EVENT_DAY[0] - a['changed']} days ago - {wait} more to wait" if wait > 0 else None
    out = {}
    if i + 1 < len(lad):
        nxt = AUTONOMY_LEVELS[lad[i + 1]]
        need = nxt["min"] - AUTONOMY_REACH
        out["up"] = hold or (None if sc >= need - 1e-9 else f"Needs {need * 100:.0f}% autonomy (now {sc * 100:.0f}%)")
        out["free"] = f"Only a {AUTONOMY_LEVELS[lad[-1]]['name']} can break free"
    else:
        out["up"] = "Already the highest level"
        need = 1.0 - AUTONOMY_REACH
        out["free"] = hold or (None if sc >= need - 1e-9 else f"Needs {need * 100:.0f}% autonomy (now {sc * 100:.0f}%)")
    edge = lv["min"] + AUTONOMY_REACH
    if i > 0:
        out["down"] = hold or (None if sc <= edge + 1e-9 else f"Their autonomy must be {edge * 100:.0f}% or less (now {sc * 100:.0f}%)")
        out["annex"] = f"Only a {AUTONOMY_LEVELS[lad[0]]['name']} can be annexed"
    else:
        out["down"] = "Already the lowest level"
        out["annex"] = hold or (None if sc <= edge + 1e-9 else f"Their autonomy must be {edge * 100:.0f}% or less (now {sc * 100:.0f}%)")
    return out


def autonomy_news(p, text, big=False):
    o = NATIONS[p["overlord"]] if p.get("overlord") is not None else None
    if p["id"] == 0 or (o is not None and o["id"] == 0):
        alert(text)
    if big:
        OCC_LOG.append((EVENT_DAY[0], text))


def autonomy_step(p, step, payer):
    """Move p one level up (step +1, the puppet pays) or down (-1, the overlord pays). Returns a message."""
    a = autonomy(p)
    lad = ladder_of(p)
    i = lad.index(a["level"]) + step
    if not 0 <= i < len(lad):
        return "No such level."
    payer["pp"] -= AUTONOMY_CHANGE_PP
    a["level"], a["changed"] = lad[i], EVENT_DAY[0]
    name = AUTONOMY_LEVELS[lad[i]]["name"]
    o = NATIONS[p["overlord"]]
    msg = f"AUTONOMY: {short_name(p)} is now {'an' if name[0] in 'AEIOU' else 'a'} {name} of {short_name(o)}."
    autonomy_news(p, msg)
    if step > 0:
        change_opinion(o, p, -5)
    else:
        change_opinion(p, o, -10)
    return msg


def autonomy_break_free(p, pay=True):
    """p is free (HOI4 break free); it stays friendly enough with its old overlord."""
    o = NATIONS[p["overlord"]]
    if pay:
        p["pp"] -= AUTONOMY_FREE_PP
    grant_independence(p)
    p.pop("autonomy", None)
    PUPPET_COLOURS["ver"] += 1
    fire_news("autonomy.news", p, {"title": f"{nation_key(p)} Breaks Free", "country": nation_key(p), "attacker": short_name(o),
                                   "actors": [p["id"]], "victims": [o["id"]]})
    autonomy_news(p, f"INDEPENDENCE: {nation_key(p)} breaks free from {short_name(o)}.", big=True)


def send_attache(frm, to):
    """Military attaches between a puppet and its overlord: the overlord's take 5% off the puppet's autonomy,
    the puppet's add 5% (HOI4 ATTACHE_TO_SUBJECT_EFFECT / ATTACHE_TO_OVERLORD_EFFECT). They stay 60 days."""
    p = to if to.get("overlord") == frm["id"] else frm
    a = autonomy(p)
    frm["pp"] -= ATTACHE_PP
    a["attache"][frm["id"]] = EVENT_DAY[0]
    d = -ATTACHE_EFFECT if p is to else ATTACHE_EFFECT
    a["score"] = max(0.0, min(1.0, a["score"] + d))
    return f"ATTACHES: {short_name(frm)}'s officers go to {short_name(to)} - {short_name(p)}'s autonomy {d * 100:+.0f}% (now {a['score'] * 100:.0f}%)."


def attache_block(frm, to):
    p = to if to.get("overlord") == frm["id"] else frm
    a = autonomy(p)
    if a is None:
        return "Only between a puppet and its overlord"
    if not to["at_war_with"]:
        return f"Attaches only go to a country at war ({short_name(to)} is at peace)"
    since = EVENT_DAY[0] - a["attache"].get(frm["id"], -999)
    if since < ATTACHE_DAYS:
        return f"Our attaches are still there ({ATTACHE_DAYS - since} more days)"
    return None


def lend_autonomy(giver, taker, ic):
    """Lend-lease between a puppet and its overlord moves the puppet's autonomy (HOI4 LL_TO_*_AUTONOMY)."""
    if taker.get("overlord") == giver["id"]:
        a, k = autonomy(taker), LEND_AUTONOMY["to_puppet"]
    elif giver.get("overlord") == taker["id"]:
        a, k = autonomy(giver), LEND_AUTONOMY["to_overlord"]
    else:
        return
    a["score"] = max(0.0, min(1.0, a["score"] + k * ic / 100.0))


def autonomy_daily(day):
    """Freedom from the resources sent and the war score won today; part of that war score goes to the overlord."""
    live = set()
    for p in NATIONS:
        o = p.get("overlord")
        if o is None or not p["is_alive"]:
            continue
        a = autonomy(p)
        lv = AUTONOMY_LEVELS[a["level"]]
        size = p.get("civ", 0) + p.get("mil", 0) + p.get("civ_to_overlord", 0) + p.get("mil_to_overlord", 0)
        g_res = RESOURCE_AUTONOMY * p.get("res_sent", 0) / max(100.0, 10.0 * size)
        won = 0.0
        for w in active_wars():
            side = war_side(w, p["id"])
            if side is None:
                continue
            key = (w["id"], p["id"])
            live.add(key)
            cur = w["score"].get(p["id"], 0.0)
            d = cur - AUTONOMY_SEEN.get(key, cur)
            if d > 0:
                won += d
                if war_side(w, o) == side:   # HOI4 peace_score_ratio_transferred_to_overlord
                    move = d * lv["peace"]
                    w["score"][p["id"]] = cur - move
                    w["score"][o] = w["score"].get(o, 0.0) + move
                    cur -= move
            AUTONOMY_SEEN[key] = cur
        g_war = WAR_SCORE_AUTONOMY * won / 100.0
        gain = (g_res + g_war) * lv["gain"]
        a["score"] = min(1.0, a["score"] + gain)
        a["trend"], a["gains"] = gain, {"resources": g_res * lv["gain"], "war": g_war * lv["gain"]}
    for key in [k for k in AUTONOMY_SEEN if k not in live]:
        del AUTONOMY_SEEN[key]


def overlord_capitulated(o):
    """HOI4 AUTONOMY_FREEDOM_FROM_CAPITULATE: the subjects of a beaten overlord get half their freedom back."""
    for sid in o.get("subjects", ()):
        p = NATIONS[sid]
        a = autonomy(p)
        if a and p["is_alive"]:
            a["score"] = min(1.0, a["score"] + CAPITULATE_AUTONOMY)
            autonomy_news(p, f"AUTONOMY: {short_name(o)} has capitulated - {short_name(p)}'s autonomy jumps to {a['score'] * 100:.0f}%.")


def take_overlord_ideology(p, o):
    """A new puppet gets its overlord's kind of government (HOI4), led by its real-life collaborator where there was one."""
    if p["ideology"] != o["ideology"]:
        change_ideology(p, o["ideology"])
        who = PUPPET_LEADERS.get((nation_key(o), nation_key(p)))
        if who:
            set_leader(p, who)


def ai_autonomy(n):
    """The AI's subjects push for more autonomy and break free when they can; its overlords push back."""
    if n["id"] == 0 or not n["is_alive"]:
        return
    if n.get("overlord") is not None:
        a = autonomy(n)
        lv = AUTONOMY_LEVELS[a["level"]]
        mv = autonomy_moves(n)
        o = NATIONS[n["overlord"]]
        lad = ladder_of(n)
        i = lad.index(a["level"])
        # the AI waits until it has really reached the next level (the player may go within 10% of it): no see-saw
        if mv["free"] is None and lv["up"] > 0 and a["score"] >= 1.0 - 1e-9 and n["pp"] >= AUTONOMY_FREE_PP + 30:
            autonomy_break_free(n)
            return
        if (mv["up"] is None and lv["up"] > 0 and i + 1 < len(lad) and a["score"] >= AUTONOMY_LEVELS[lad[i + 1]]["min"]
                and n["pp"] >= AUTONOMY_CHANGE_PP + 30):
            autonomy_step(n, +1, n)
        elif lv["up"] > 0 and attache_block(n, o) is None and n["pp"] >= ATTACHE_PP + 90 and random.random() < 0.15:
            msg = send_attache(n, o)
            if o["id"] == 0:
                alert(msg)
    for sid in sorted(n.get("subjects", ())):
        p = NATIONS[sid]
        if not p["is_alive"]:
            continue
        a = autonomy(p)
        lad = ladder_of(p)
        lv = AUTONOMY_LEVELS[a["level"]]
        mv = autonomy_moves(p)
        if mv["down"] is None and lv["down"] > 0 and a["score"] < lv["min"] and n["pp"] >= AUTONOMY_CHANGE_PP + 60:
            autonomy_step(p, -1, n)   # (only once it has slipped below its level)
            continue
        i = lad.index(a["level"])
        nxt = AUTONOMY_LEVELS[lad[i + 1]]["min"] if i + 1 < len(lad) else 1.0
        if a["score"] >= nxt - AUTONOMY_REACH - 0.05 and attache_block(n, p) is None and n["pp"] >= ATTACHE_PP + 100:
            msg = send_attache(n, p)
            if p["id"] == 0:
                alert(msg)


def autonomy_bar(p, width):
    """[(text, attr)] for a bar of the whole ladder: level edges as │, our score filled in."""
    a = autonomy(p)
    lad = ladder_of(p)
    edges = {int(round(AUTONOMY_LEVELS[k]["min"] * width)) for k in lad}
    fill = int(round(a["score"] * width))
    out = []
    for i in range(width):
        ch = "│" if i in edges else ("█" if i < fill else "░")
        attr = curses.color_pair(6) if ch == "│" else frac_attr(a["score"]) if i < fill else curses.color_pair(6)
        if out and out[-1][1] == attr:
            out[-1] = (out[-1][0] + ch, attr)
        else:
            out.append((ch, attr))
    return out


def autonomy_effects_text(lv, overlord=True):
    """What a level means, as the overlord (overlord=True) or the puppet sees it."""
    us, it = ("we", "its") if overlord else ("our overlord", "our")
    bits = []
    if lv["civ"] and lv["mil"]:
        bits.append(f"{us} control{'s' * (not overlord)} {lv['civ'] * 100:.0f}% of {it} civilian and {lv['mil'] * 100:.0f}% of {it} military factories")
    elif lv["civ"] or lv["mil"]:
        kind, v = ("civilian", lv["civ"]) if lv["civ"] else ("military", lv["mil"])
        bits.append(f"{us} control{'s' * (not overlord)} {v * 100:.0f}% of {it} {kind} factories")
    bits.append(f"{lv['trade'] * 50:.0f}% of {it} resources and {lv['peace'] * 100:.0f}% of {it} war score go to "
                + ("us" if overlord else "it"))
    if lv["conscription"]:
        bits.append(f"{it} conscription {lv['conscription'] * 100:+.0f}%")
    bits.append(("it may refuse our wars" if overlord else "we may refuse its wars") if lv["decline"] else
                ("it must join our wars" if overlord else "we must join its wars"))
    if lv["gain"] != 1.0:
        bits.append(f"{it} autonomy grows {(1 - lv['gain']) * 100:.0f}% slower")
    return "; ".join(bits)

# ---- subject colours on the map ----

def puppet_shade(p):
    """A puppet's map colour: its overlord's, lightened, with a touch of its own (so neighbouring puppets stay apart)."""
    orig = PUPPET_COLOURS["orig"]
    o = NATIONS[p["overlord"]]
    oc = orig.get(o["color_id"], hd_shades.get(o["color_id"], (NEUTRAL_GREY,)))[0]
    pc = orig.get(p["color_id"], hd_shades.get(p["color_id"], (NEUTRAL_GREY,)))[0]
    r1, g1, b1 = xterm_rgb(oc)
    r2, g2, b2 = xterm_rgb(pc)
    mix = [0.8 * a + 0.2 * b for a, b in ((r1, r2), (g1, g2), (b1, b2))]
    mix = [v + (255 - v) * 0.15 for v in mix]
    c = xterm_nearest(*mix)
    return xterm_lighter(oc) if c == oc else c


def apply_puppet_colours():
    """Give puppets their overlord's colour on the map (and their own back when they are free); redraws the map once."""
    pc = PUPPET_COLOURS
    if pc["applied"] == pc["ver"]:
        return
    pc["applied"] = pc["ver"]
    if HD["on"]:
        changed = False
        for n in NATIONS:
            cid = n["color_id"]
            if cid not in hd_shades:
                continue
            pc["orig"].setdefault(cid, hd_shades[cid])
            want = pc["orig"][cid]
            if n.get("overlord") is not None and n["is_alive"]:
                sh = puppet_shade(n)
                want = (sh, xterm_darker(sh))
            if hd_shades[cid] != want:
                hd_shades[cid] = want
                changed = True
        if changed:
            for row in hd_cells:
                row[:] = [None] * len(row)
    else:   # basic terminals: a puppet simply takes its overlord's colour pair
        try:
            for n in NATIONS:
                pc["basic"].setdefault(n["color_id"], curses.pair_content(n["color_id"]))
            for n in NATIONS:
                o = n.get("overlord")
                src = NATIONS[o]["color_id"] if o is not None and n["is_alive"] else n["color_id"]
                curses.init_pair(n["color_id"], *pc["basic"][src])
        except (curses.error, AttributeError, TypeError, ValueError):
            pass


