# ---- HOI4's subject interactions (the diplomacy screen and the territory screen use these) ----

SUBJECT_ACTIONS = ("pup_down", "pup_annex", "pup_attache", "pup_free", "pup_up", "pup_breakfree", "pup_attache_up")


def pp_why(n, cost):
    return None if n["pp"] >= cost else f"Needs {cost} PP (we have {n['pp']:.0f})"


def subject_actions(player, other):
    """[(id, label, PP cost, why not or None, what it does)] between us and our puppet, or us and our overlord."""
    out = []
    if other.get("overlord") == player["id"] and other["is_alive"]:
        p = other
        a, lad = autonomy(p), ladder_of(p)
        i, mv = lad.index(a["level"]), autonomy_moves(p)
        if i > 0:
            low = AUTONOMY_LEVELS[lad[i - 1]]
            out.append(("pup_down", f"Lower its autonomy: make it {'an' if low['name'][0] in 'AEIOU' else 'a'} {low['name']}", AUTONOMY_CHANGE_PP,
                        mv["down"] or pp_why(player, AUTONOMY_CHANGE_PP), autonomy_effects_text(low)))
        else:
            out.append(("pup_annex", f"Annex {short_name(p)}", AUTONOMY_ANNEX_PP, mv["annex"] or pp_why(player, AUTONOMY_ANNEX_PP),
                        "Its land, army and fleet become ours"))
        out.append(("pup_attache", "Send military attaches", ATTACHE_PP, attache_block(player, p) or pp_why(player, ATTACHE_PP),
                    f"Its autonomy -{ATTACHE_EFFECT * 100:.0f}% (they stay {ATTACHE_DAYS} days)"))
        out.append(("pup_free", "Grant independence", 0, None, "It is a free country again (its opinion of us +20)"))
    elif player.get("overlord") == other["id"]:
        p = player
        a, lad = autonomy(p), ladder_of(p)
        i, mv = lad.index(a["level"]), autonomy_moves(p)
        if i + 1 < len(lad):
            up = AUTONOMY_LEVELS[lad[i + 1]]
            out.append(("pup_up", f"Ask for more autonomy: become {'an' if up['name'][0] in 'AEIOU' else 'a'} {up['name']}", AUTONOMY_CHANGE_PP,
                        mv["up"] or pp_why(player, AUTONOMY_CHANGE_PP), autonomy_effects_text(up, overlord=False)))
        else:
            out.append(("pup_breakfree", "Break free", AUTONOMY_FREE_PP, mv["free"] or pp_why(player, AUTONOMY_FREE_PP),
                        "We are a free country again"))
        out.append(("pup_attache_up", "Send attaches to our overlord", ATTACHE_PP, attache_block(player, other) or pp_why(player, ATTACHE_PP),
                    f"Our autonomy +{ATTACHE_EFFECT * 100:.0f}% (they stay {ATTACHE_DAYS} days)"))
    return out


def do_subject_action(aid, player, other, pm, units):
    a = {x[0]: x for x in subject_actions(player, other)}.get(aid)
    if a is None:
        return "LOCKED: not possible now."
    if a[3]:
        return f"LOCKED: {a[3]}."
    if aid == "pup_down":
        return autonomy_step(other, -1, player)
    if aid == "pup_annex":
        player["pp"] -= AUTONOMY_ANNEX_PP
        annex_nation(other, player, pm, units)
        update_industry(pm)
        return f"SUCCESS: {nation_key(other)} is annexed and becomes part of our country."
    if aid in ("pup_attache", "pup_attache_up"):
        return send_attache(player, other)
    if aid == "pup_free":
        grant_independence(other)
        other.pop("autonomy", None)
        return f"{nation_key(other)} is independent again."
    if aid == "pup_up":
        return autonomy_step(player, +1, player)
    if aid == "pup_breakfree":
        autonomy_break_free(player)
        return f"INDEPENDENCE: we break free from {short_name(other)}!"
    return None


# ======================= THE AIR FORCE AS IN HOI4: AIR BASES, MISSIONS, THE AIR STOCKPILE =======================
# On the air map ([F10]) our air bases show the planes on them. [ENTER] on an air base opens it: its wings,
# new wings from the air stockpile, a bigger base. [ENTER] anywhere else lists every wing that can reach that
# zone. With a wing (or several) picked, the side panel lists the missions over the zone under the cursor and
# [1]-[9] gives one, as HOI4's mission buttons do.

MISSION_ORDER = ("AIR_SUPERIORITY", "INTERCEPT", "CAS", "STRAT_BOMB", "NAVAL_STRIKE", "NAVAL_PATROL", "PORT_STRIKE", "TRAINING")


def wing_by_id(i):
    return next((w for w in AIR["wings"] if w.id == i), None)


def mission_block_reach(w, z, m):
    """mission_block, except that a wing out of range is fine when another of our bases reaches the zone (it moves)."""
    why = mission_block(w, z, m)
    if why and why.startswith("Out of range") and best_base(NATIONS[w.nation_id], z, wing_range(w)) is not None:
        return None
    return why


def mission_choices(wings, z):
    """[(mission, why not or None)] over zone z for these wings: every mission one of them can fly, then stand by."""
    if z is None or z < 0 or not wings:
        return []
    ms = sorted({m for w in wings for m in FAMILY_INFO[w.family][2]}, key=MISSION_ORDER.index)
    out = []
    for m in ms:
        whys = [mission_block_reach(w, z, m) for w in wings if m in FAMILY_INFO[w.family][2]]
        out.append((m, None if any(x is None for x in whys) else whys[0]))
    out.append(("IDLE", None))
    return out


def send_wings(wings, z, mission):
    """Give these wings a mission over zone z (a wing out of range moves to our base that reaches it best)."""
    if mission == "IDLE":
        for w in wings:
            set_wing_mission(w, None, "IDLE")
        return (f"{wings[0].name} stands by at {STATES[wings[0].base]['name']}." if len(wings) == 1 else
                f"{len(wings)} wings stand by at their air bases.")
    done, moved, cant = [], [], []
    for w in wings:
        if mission not in FAMILY_INFO[w.family][2]:
            cant.append(w)
            continue
        why = mission_block(w, z, mission)
        if why and why.startswith("Out of range"):
            alt = best_base(NATIONS[w.nation_id], z, wing_range(w))
            if alt is not None:
                w.base = alt["id"]
                refresh_base_load()
                moved.append(alt["name"])
                why = mission_block(w, z, mission)
        if why:
            cant.append(w)
            continue
        set_wing_mission(w, z, mission)
        done.append(w)
    if not done:
        return f"LOCKED: {mission_block(cant[0], z, mission) if cant else 'no wing can fly it'}."
    name = AIR_MISSION_INFO[mission][0]
    where = AIR_ZONES[z]["name"] if mission != "TRAINING" else "home"
    if len(done) == 1:
        w = done[0]
        msg = f"{w.name}: {name} over {where}" if mission != "TRAINING" else f"{w.name}: Training at {STATES[w.base]['name']}"
        if mission != "TRAINING":
            msg += f" ({coverage(w.base, z, wing_range(w)) * 100:.0f}% in range)"
    else:
        msg = f"{len(done)} wings: {name}" + (f" over {where}" if mission != "TRAINING" else "")
    if moved:
        msg += f" - moved to {', '.join(dict.fromkeys(moved))}"
    if cant:
        msg += f"; {len(cant)} can't ({cant[0].name})"
    return msg + f". {AIR_MISSION_INFO[mission][2]}."


def air_output(n):
    """Planes a day from our production lines, by kind."""
    out = {}
    for line in n.get("lines", []):
        if EQUIPMENT[line["eq"]].get("air") and line["f"]:
            out[line["eq"]] = out.get(line["eq"], 0.0) + line.get("daily", 0.0)
    return out


def air_needed(n, fam):
    return sum(max(0, w.size - w.planes) for w in AIR["wings"] if w.nation_id == n["id"] and w.family == fam)


def base_planes(sid):
    return sum(w.planes for w in AIR["wings"] if w.base == sid)


def fighter_range(n):
    """Our best fighter's range (km)."""
    g = best_gen(n, "fighter")
    return plane_stat("fighter", max(min(PLANE_STATS["fighter"]), g), "rng")


def base_reach(s, rng=700):
    """The zones a base reaches with planes of this range, best first: [(coverage, zone)]."""
    out = []
    for z in AIR_ZONES:
        if z["tiles"]:
            c = coverage(s["id"], z["id"], rng)
            if c > 0:
                out.append((c, z["id"]))
    return sorted(out, reverse=True)


# ---- the AIR BASE / AIR ZONE screen ----

def air_view_rows(player, view):
    if view.get("rebase") is not None:
        w = wing_by_id(view["rebase"])
        if w is None:
            view["rebase"] = None
        else:
            here = STATES[w.base]
            return [("base", s) for s in sorted(own_bases(player), key=lambda s: tile_km((s["x"], s["y"]), (here["x"], here["y"])))]
    if view.get("pick") is not None:
        wings = [w for w in (wing_by_id(i) for i in view["pick"]) if w]
        return [("mission", c) for c in mission_choices(wings, view["zone"])]
    mine = [w for w in AIR["wings"] if w.nation_id == player["id"]]
    if view["mode"] == "base":
        rows = [("wing", w) for w in sorted((w for w in mine if w.base == view["sid"]),
                                            key=lambda w: (AIR_FAMILIES.index(w.family), w.name))]
        rows += [("deploy", f) for f in AIR_FAMILIES if player["stockpile"].get(f, 0) > 0 or best_gen(player, f) >= 0]
        return rows
    z = view["zone"]
    here = [w for w in mine if w.zone == z and w.mission not in ("IDLE", "TRAINING")]
    rest = []
    for w in mine:
        if w in here:
            continue
        cov = coverage(w.base, z, wing_range(w))
        if cov <= 0:
            alt = best_base(player, z, wing_range(w))
            cov = coverage(alt["id"], z, wing_range(w)) * 0.999 if alt else 0.0
        if cov > 0:
            rest.append((-cov, AIR_FAMILIES.index(w.family), w.name, w))
    return [("wing", w) for w in here] + [("wing", r[-1]) for r in sorted(rest, key=lambda r: r[:3])]


def draw_air_view(stdscr, player, view, rows, sel, alert):
    term_h, term_w = stdscr.getmaxyx()
    H, W = term_h - 1, term_w - 1
    x_max, width = W - 2, W - 4
    base_mode = view["mode"] == "base"
    picking, rebasing = view.get("pick") is not None, view.get("rebase") is not None
    if rebasing:
        controls = "[↑↓] Air base  [ENTER] Move the wing there  [ESC] Back"
    elif picking:
        controls = "[↑↓] Mission  [ENTER] Fly it  [ESC] Back"
    elif base_mode:
        controls = ("[↑↓] Select  [ENTER] Send the wing / Deploy  [SPACE] Mark  [M] Mission  [R] Other base  [+/-] Size  "
                    "[DEL] Disband  [B] Bigger base  [ESC] Back")
    else:
        controls = "[↑↓] Select  [ENTER] Choose a mission here  [SPACE] Mark wings  [ESC] Air map"
    draw_frame(stdscr, H, W, "AIR BASE" if base_mode else "AIR ZONE", controls)
    key = nation_key(player)
    draw_flag(stdscr, 1, 2, key, "big")
    marked = view.setdefault("marked", set())
    if base_mode:
        s = STATES[view["sid"]]
        cap, load = base_capacity(s), AIR["base_load"].get(s["id"], 0)
        draw_parts(stdscr, 1, 14, [(s["name"].upper(), curses.A_BOLD), (f"   air base level {s.get('air_base', 0)}", curses.color_pair(3) | curses.A_BOLD),
                                   (f"   {load}/{cap} planes", frac_attr(1 - min(1.0, load / max(1, cap))) | curses.A_BOLD),
                                   ("   (too many: less efficient)" if load > cap else "", curses.color_pair(1)),
                                   ("   anti-air ", curses.color_pair(6)), (str(s.get("aa", 0)), curses.A_BOLD),
                                   ("   radar ", curses.color_pair(6)), (str(s.get("radar", 0)), curses.A_BOLD),
                                   (f"   bomb damage {s['bomb'] * 100:.0f}%" if s.get("bomb", 0) >= 0.05 else "", curses.color_pair(1))], x_max)
        rng = fighter_range(player)
        reach = base_reach(s, rng)
        draw_parts(stdscr, 2, 14, [(f"Our fighters ({plane_name(player, 'fighter', max(0, best_gen(player, 'fighter')))}, {rng:.0f} km) reach: ",
                                    curses.color_pair(6)),
                                   (fit(", ".join(f"{AIR_ZONES[z]['name']} {c * 100:.0f}%" for c, z in reach[:7]) or "nothing", width - 40),
                                    curses.A_NORMAL)], x_max)
    else:
        z = view["zone"]
        zone = AIR_ZONES[z]
        share = air_share(z, player["id"])
        parts = [(zone["name"].upper(), curses.A_BOLD), ("  sea zone" if zone["sea"] else "  over land", curses.color_pair(6))]
        if share is not None:
            parts += [("   the sky: ", curses.color_pair(6)), (bar(share, 10), frac_attr(share)), (f" {share * 100:.0f}% ours", curses.A_BOLD),
                      ("   enemy planes seen ", curses.color_pair(6)),
                      (f"~{zone_planes(z, lambda w: w.nation_id in player['at_war_with'])}", curses.color_pair(1) | curses.A_BOLD)]
        else:
            parts.append(("   no air war here", curses.color_pair(6)))
        draw_parts(stdscr, 1, 14, parts, x_max)
        ours = {}
        for w in AIR["wings"]:
            if w.zone == z and w.nation_id == player["id"] and w.mission not in ("IDLE", "TRAINING"):
                ours[w.mission] = ours.get(w.mission, 0) + w.planes
        draw_parts(stdscr, 2, 14, [("Our missions here: ", curses.color_pair(6)),
                                   ("  ".join(f"{AIR_MISSION_INFO[m][0]} {k}" for m, k in ours.items()) or "none", curses.color_pair(2) | curses.A_BOLD)],
                   x_max)
    stock = [(f, player["stockpile"].get(f, 0)) for f in AIR_FAMILIES if player["stockpile"].get(f, 0) or best_gen(player, f) >= 0]
    rate = air_output(player)
    draw_parts(stdscr, 3, 14, [("AIR STOCKPILE: ", curses.color_pair(3) | curses.A_BOLD)] +
               [(f"{FAMILY_INFO[f][1]} {k}" + (f" (+{rate[f]:.1f}/day)" if rate.get(f) else "") + "  ", curses.A_NORMAL) for f, k in stock], x_max)
    draw_rule(stdscr, 4, 0, W - 1, heavy=True)
    if rebasing:
        w = wing_by_id(view["rebase"])
        title = f"MOVE {w.name.upper()} TO ANOTHER AIR BASE (now at {STATES[w.base]['name']})"
    elif picking:
        n_w = len(view["pick"])
        title = f"MISSION OVER {AIR_ZONES[view['zone']]['name'].upper()} FOR " + (wing_by_id(view["pick"][0]).name.upper() if n_w == 1 else f"{n_w} WINGS")
    elif base_mode:
        title = "WINGS AT THIS BASE, AND NEW WINGS FROM THE AIR STOCKPILE"
    else:
        title = "OUR WINGS OVER THIS ZONE, THEN ALL THE OTHERS THAT CAN REACH IT (best in range first)"
    safe_draw(stdscr, 5, 3, fit(title, width), curses.color_pair(3) | curses.A_BOLD)
