                        routes_found = 0
                        shipped, ship_err = 0, ""
                        walkable = land_reach(NATIONS[0], political_map, world_map,
                                              start=[(u.x, u.y) for u in selected_units if u.sea is None])
                        movers = [u for u in selected_units if u.sea is None]
                        spots = spread_targets((dest_x, dest_y), len(movers), NATIONS[0], units, political_map, world_map)
