                            ordered_count += 1
                            if (tx, ty) in walkable:
                                u.transfer = None
                                u.set_target(tx, ty, world_map, political_map)
                                u.is_guarding = False
                                u.order = None
                                if u.path or (u.x, u.y) == (tx, ty):
                                    routes_found += 1
