                        g_pool = GENERALS_POOL.get(country_clean, GENERALS_POOL["Generic"])
                        gen = g_pool[(new_id - 1) % len(g_pool)]
                        new_army = ArmyGroup(new_id, f"Army Group {new_id}", general=gen, color_id=(new_id % 6) + 1)
